window.BibleBooks=window.BibleBooks||{};window.BibleBooks["PHM"]={"book":"PHM","editions":{"hin2017":[[1,1,"पौलुस की ओर से जो मसीह यीशु का कैदी है, और भाई तीमुथियुस की ओर से हमारे प्रिय सहकर्मी फिलेमोन,","paulusa kī ora se jo masīha yīśu kā kaidī hai, aura bhāī tīmuthiyusa kī ora se hamāre priya sahakarmī philemona,",null],[1,2,"और बहन अफफिया, और हमारे साथी योद्धा अरखिप्पुस और फिलेमोन के घर की कलीसिया के नाम।","aura bahana aphaphiyā, aura hamāre sāthī yoddhā arakhippusa aura philemona ke ghara kī kalīsiyā ke nāma.",null],[1,3,"हमारे पिता परमेश्वर और प्रभु यीशु मसीह की ओर से अनुग्रह और शान्ति तुम्हें मिलती रहे।","hamāre pitā parameśvara aura prabhu yīśu masīha kī ora se anugraha aura śānti tumheṃ milatī rahe.",null],[1,4,"मैं सदा परमेश्वर का धन्यवाद करता हूँ; और अपनी प्रार्थनाओं में भी तुझे स्मरण करता हूँ।","maiṃ sadā parameśvara kā dhanyavāda karatā hūm̐; aura apanī prārthanāoṃ meṃ bhī tujhe smaraṇa karatā hūm̐.",null],[1,5,"क्योंकि मैं तेरे उस प्रेम और विश्वास की चर्चा सुनकर, जो प्रभु यीशु पर और सब पवित्र लोगों के साथ है।","kyoṃki maiṃ tere usa prema aura viśvāsa kī carcā sunakara, jo prabhu yīśu para aura saba pavitra logoṃ ke sātha hai.",null],[1,6,"मैं प्रार्थना करता हूँ कि, विश्वास में तुम्हारी सहभागिता हर अच्छी बात के ज्ञान के लिए प्रभावी हो जो मसीह में हमारे पास है।","maiṃ prārthanā karatā hūm̐ ki, viśvāsa meṃ tumhārī sahabhāgitā hara acchī bāta ke jñāna ke lie prabhāvī ho jo masīha meṃ hamāre pāsa hai.",null],[1,7,"क्योंकि हे भाई, मुझे तेरे प्रेम से बहुत आनन्द और शान्ति मिली है, इसलिए, कि तेरे द्वारा पवित्र लोगों के मन हरे भरे हो गए हैं।","kyoṃki he bhāī, mujhe tere prema se bahuta ānanda aura śānti milī hai, isalie, ki tere dvārā pavitra logoṃ ke mana hare bhare ho gae haiṃ.",null],[1,8,"इसलिए यद्यपि मुझे मसीह में बड़ा साहस है, कि जो बात ठीक है, उसकी आज्ञा तुझे दूँ।","isalie yadyapi mujhe masīha meṃ baṛā sāhasa hai, ki jo bāta ṭhīka hai, usakī ājñā tujhe dūm̐.",null],[1,9,"तो भी मुझ बूढ़े पौलुस को जो अब मसीह यीशु के लिये कैदी हूँ, यह और भी भला जान पड़ा कि प्रेम से विनती करूँ।","to bhī mujha būṛhe paulusa ko jo aba masīha yīśu ke liye kaidī hūm̐, yaha aura bhī bhalā jāna paṛā ki prema se vinatī karūm̐.",null],[1,10,"मैं अपने बच्चे उनेसिमुस के लिये जो मुझसे मेरी कैद में जन्मा है तुझ से विनती करता हूँ।","maiṃ apane bacce unesimusa ke liye jo mujhase merī kaida meṃ janmā hai tujha se vinatī karatā hūm̐.",null],[1,11,"वह तो पहले तेरे कुछ काम का न था, पर अब तेरे और मेरे दोनों के बड़े काम का है।","vaha to pahale tere kucha kāma kā na thā, para aba tere aura mere donoṃ ke baṛe kāma kā hai.",null],[1,12,"उसी को अर्थात् जो मेरे हृदय का टुकड़ा है, मैंने उसे तेरे पास लौटा दिया है।","usī ko arthāt jo mere hṛdaya kā ṭukaṛā hai, maiṃne use tere pāsa lauṭā diyā hai.",null],[1,13,"उसे मैं अपने ही पास रखना चाहता था कि वह तेरी ओर से इस कैद में जो सुसमाचार के कारण है, मेरी सेवा करे।","use maiṃ apane hī pāsa rakhanā cāhatā thā ki vaha terī ora se isa kaida meṃ jo susamācāra ke kāraṇa hai, merī sevā kare.",null],[1,14,"पर मैंने तेरी इच्छा बिना कुछ भी करना न चाहा कि तेरा यह उपकार दबाव से नहीं पर आनन्द से हो।","para maiṃne terī icchā binā kucha bhī karanā na cāhā ki terā yaha upakāra dabāva se nahīṃ para ānanda se ho.",null],[1,15,"क्योंकि क्या जाने वह तुझ से कुछ दिन तक के लिये इसी कारण अलग हुआ कि सदैव तेरे निकट रहे।","kyoṃki kyā jāne vaha tujha se kucha dina taka ke liye isī kāraṇa alaga huā ki sadaiva tere nikaṭa rahe.",null],[1,16,"परन्तु अब से दास के समान नहीं, वरन् दास से भी उत्तम, अर्थात् भाई के समान रहे जो मेरा तो विशेष प्रिय है ही, पर अब शरीर में और प्रभु में भी, तेरा भी विशेष प्रिय हो।","parantu aba se dāsa ke samāna nahīṃ, varan dāsa se bhī uttama, arthāt bhāī ke samāna rahe jo merā to viśeṣa priya hai hī, para aba śarīra meṃ aura prabhu meṃ bhī, terā bhī viśeṣa priya ho.",null],[1,17,"यदि तू मुझे अपना सहभागी समझता है, तो उसे इस प्रकार ग्रहण कर जैसे मुझे।","yadi tū mujhe apanā sahabhāgī samajhatā hai, to use isa prakāra grahaṇa kara jaise mujhe.",null],[1,18,"और यदि उसने तेरी कुछ हानि की है, या उस पर तेरा कुछ आता है, तो मेरे नाम पर लिख ले।","aura yadi usane terī kucha hāni kī hai, yā usa para terā kucha ātā hai, to mere nāma para likha le.",null],[1,19,"मैं पौलुस अपने हाथ से लिखता हूँ, कि मैं आप भर दूँगा; और इसके कहने की कुछ आवश्यकता नहीं, कि मेरा कर्ज जो तुझ पर है वह तू ही है।","maiṃ paulusa apane hātha se likhatā hūm̐, ki maiṃ āpa bhara dūm̐gā; aura isake kahane kī kucha āvaśyakatā nahīṃ, ki merā karja jo tujha para hai vaha tū hī hai.",null],[1,20,"हे भाई, यह आनन्द मुझे प्रभु में तेरी ओर से मिले, मसीह में मेरे जी को हरा भरा कर दे।","he bhāī, yaha ānanda mujhe prabhu meṃ terī ora se mile, masīha meṃ mere jī ko harā bharā kara de.",null],[1,21,"मैं तेरे आज्ञाकारी होने का भरोसा रखकर, तुझे लिखता हूँ और यह जानता हूँ, कि जो कुछ मैं कहता हूँ, तू उससे कहीं बढ़कर करेगा।","maiṃ tere ājñākārī hone kā bharosā rakhakara, tujhe likhatā hūm̐ aura yaha jānatā hūm̐, ki jo kucha maiṃ kahatā hūm̐, tū usase kahīṃ baṛhakara karegā.",null],[1,22,"और यह भी, कि मेरे लिये ठहरने की जगह तैयार रख; मुझे आशा है, कि तुम्हारी प्रार्थनाओं के द्वारा मैं तुम्हें दे दिया जाऊँगा।","aura yaha bhī, ki mere liye ṭhaharane kī jagaha taiyāra rakha; mujhe āśā hai, ki tumhārī prārthanāoṃ ke dvārā maiṃ tumheṃ de diyā jāūm̐gā.",null],[1,23,"इपफ्रास जो मसीह यीशु में मेरे साथ कैदी है","ipaphrāsa jo masīha yīśu meṃ mere sātha kaidī hai",null],[1,24,"और मरकुस और अरिस्तर्खुस और देमास और लूका जो मेरे सहकर्मी हैं; इनका तुझे नमस्कार।","aura marakusa aura aristarkhusa aura demāsa aura lūkā jo mere sahakarmī haiṃ; inakā tujhe namaskāra.",null],[1,25,"हमारे प्रभु यीशु मसीह का अनुग्रह तुम्हारी आत्मा पर होता रहे। आमीन।","hamāre prabhu yīśu masīha kā anugraha tumhārī ātmā para hotā rahe. āmīna.",null]],"pan":[[1,1,"ਪੌਲੁਸ ਵੱਲੋਂ, ਜਿਹੜਾ ਮਸੀਹ ਯਿਸੂ ਦਾ ਕੈਦੀ ਹਾਂ ਅਤੇ ਭਰਾ ਤਿਮੋਥਿਉਸ ਵੱਲੋਂ। ਅੱਗੇ ਯੋਗ ਸਾਡੇ ਪਿਆਰੇ ਅਤੇ ਸਹਿਕਰਮੀ ਫਿਲੇਮੋਨ l","paulusa vallōṁ, jihaṛā masīha yisū dā kaidī hāṁ atē bharā timōthiusa vallōṁ. aggē yōga sāḍē piārē atē sahikaramī philēmōna l",null],[1,2,"ਅਤੇ ਸਾਡੀ ਭੈਣ ਅੱਫਿਆ, ਸਾਡੇ ਨਾਲ ਦੇ ਸਿਪਾਹੀ ਅਰਖਿੱਪੁਸ ਅਤੇ ਉਸ ਕਲੀਸਿਯਾ ਨੂੰ ਜੋ ਤੇਰੇ ਘਰ ਵਿੱਚ ਹੈ।","atē sāḍī bhaiṇa apphiā, sāḍē nāla dē sipāhī arakhippusa atē usa kalīsiyā nūṁ jō tērē ghara vicca hai.",null],[1,3,"ਪਰਮੇਸ਼ੁਰ ਸਾਡੇ ਪਿਤਾ ਅਤੇ ਪ੍ਰਭੂ ਯਿਸੂ ਮਸੀਹ ਦੀ ਵੱਲੋਂ ਤੁਹਾਨੂੰ ਕਿਰਪਾ ਅਤੇ ਸ਼ਾਂਤੀ ਮਿਲਦੀ ਰਹੇ।","paramēśura sāḍē pitā atē prabhū yisū masīha dī vallōṁ tuhānūṁ kirapā atē śāṁtī miladī rahē.",null],[1,4,"ਤੇਰਾ ਪਿਆਰ ਅਤੇ ਵਿਸ਼ਵਾਸ ਜੋ ਪ੍ਰਭੂ ਯਿਸੂ ਅਤੇ ਸਭਨਾਂ ਸੰਤਾਂ ਦੇ ਨਾਲ ਹੈ।","tērā piāra atē viśavāsa jō prabhū yisū atē sabhanāṁ saṁtāṁ dē nāla hai.",null],[1,5,"ਉਹ ਦੀ ਖ਼ਬਰ ਸੁਣ ਕੇ ਮੈਂ ਆਪਣੀਆਂ ਪ੍ਰਾਰਥਨਾਵਾਂ ਵਿੱਚ ਤੇਰੀ ਗੱਲ ਕਰਦਿਆਂ, ਸਦਾ ਆਪਣੇ ਪਰਮੇਸ਼ੁਰ ਦਾ ਧੰਨਵਾਦ ਕਰਦਾ ਹਾਂ।","uha dī k͟habara suṇa kē maiṁ āpaṇīāṁ prārathanāvāṁ vicca tērī galla karadiāṁ, sadā āpaṇē paramēśura dā dhannavāda karadā hāṁ.",null],[1,6,"ਜੋ ਤੇਰੇ ਵਿਸ਼ਵਾਸ ਦੀ ਸਾਂਝ, ਤੁਹਾਡੀ ਹਰੇਕ ਨੇਕੀ ਦੀ ਪਛਾਣ ਦੇ ਦੁਆਰਾ ਜੋ ਮਸੀਹ ਵਿੱਚ ਹੈ, ਪ੍ਰਭਾਵਸ਼ਾਲੀ ਹੋਵੇ।","jō tērē viśavāsa dī sāṁjha, tuhāḍī harēka nēkī dī pachāṇa dē duārā jō masīha vicca hai, prabhāvaśālī hōvē.",null],[1,7,"ਕਿਉਂ ਜੋ ਭਰਾ, ਤੇਰੇ ਪਿਆਰ ਤੋਂ ਮੈਨੂੰ ਵੱਡਾ ਅਨੰਦ ਅਤੇ ਤਸੱਲੀ ਹੋਈ, ਇਸ ਲਈ ਜੋ ਤੇਰੇ ਕਾਰਨ ਸੰਤਾਂ ਦਾ ਦਿਲ ਤਰੋ ਤਾਜ਼ਾ ਹੋਇਆ ਹੈ।","kiuṁ jō bharā, tērē piāra tōṁ mainūṁ vaḍḍā anaṁda atē tasallī hōī, isa laī jō tērē kārana saṁtāṁ dā dila tarō tāzā hōiā hai.",null],[1,8,"ਸੋ ਭਾਵੇਂ ਮਸੀਹ ਵਿੱਚ ਮੈਨੂੰ ਦਲੇਰੀ ਤਾਂ ਬਹੁਤ ਹੈ ਕਿ ਜੋ ਕੁਝ ਉੱਚਿਤ ਹੈ ਉਸ ਵਿਖੇ ਤੈਨੂੰ ਹੁਕਮ ਦੇਵਾਂ।","sō bhāvēṁ masīha vicca mainūṁ dalērī tāṁ bahuta hai ki jō kujha uccita hai usa vikhē tainūṁ hukama dēvāṁ.",null],[1,9,"ਪਰ ਪਿਆਰ ਦਾ ਵਾਸਤਾ ਪਾ ਕੇ ਮੈਂ ਪੌਲੁਸ ਬੁੱਢਾ ਅਤੇ ਮਸੀਹ ਯਿਸੂ ਦਾ ਕੈਦੀ ਵੀ ਹੋ ਕੇ ਬੇਨਤੀ ਕਰਦਾ ਹਾਂ।","para piāra dā vāsatā pā kē maiṁ paulusa buḍḍhā atē masīha yisū dā kaidī vī hō kē bēnatī karadā hāṁ.",null],[1,10,"ਮੈਂ ਆਪਣੇ ਬੱਚੇ ਉਨੇਸਿਮੁਸ ਦੇ ਲਈ ਜਿਸਨੇ ਕੈਦ ਵਿੱਚ ਮੇਰੇ ਤੋਂ ਜਨਮ ਲਿਆ ਤੇਰੇ ਅੱਗੇ ਬੇਨਤੀ ਕਰਦਾ ਹਾਂ l","maiṁ āpaṇē baccē unēsimusa dē laī jisanē kaida vicca mērē tōṁ janama liā tērē aggē bēnatī karadā hāṁ l",null],[1,11,"ਜਿਹੜਾ ਪਹਿਲਾਂ ਤੇਰੇ ਕਿਸੇ ਕੰਮ ਦਾ ਨਹੀਂ ਸੀ, ਪਰ ਹੁਣ ਤੇਰੇ ਅਤੇ ਮੇਰੇ ਬਹੁਤ ਕੰਮ ਦਾ ਹੈ।","jihaṛā pahilāṁ tērē kisē kamma dā nahīṁ sī, para huṇa tērē atē mērē bahuta kamma dā hai.",null],[1,12,"ਉਸੇ ਨੂੰ ਜੋ ਮੇਰੇ ਆਪਣੇ ਕਲੇਜੇ ਦਾ ਟੁੱਕੜਾ ਹੈ, ਮੈਂ ਤੇਰੇ ਕੋਲ ਵਾਪਿਸ ਭੇਜਿਆ ਹੈ।","usē nūṁ jō mērē āpaṇē kalējē dā ṭukkaṛā hai, maiṁ tērē kōla vāpisa bhējiā hai.",null],[1,13,"ਮੈਂ ਚਾਹੁੰਦਾ ਸੀ ਜੋ ਉਹ ਨੂੰ ਆਪਣੇ ਹੀ ਕੋਲ ਰੱਖਾਂ, ਤਾਂ ਕਿ ਤੇਰੇ ਵੱਲੋਂ ਖੁਸ਼ਖਬਰੀ ਦੇ ਬੰਧਨਾਂ ਵਿੱਚ ਮੇਰੀ ਸੇਵਾ ਕਰੇ।","maiṁ cāhuṁdā sī jō uha nūṁ āpaṇē hī kōla rakkhāṁ, tāṁ ki tērē vallōṁ khuśakhabarī dē baṁdhanāṁ vicca mērī sēvā karē.",null],[1,14,"ਪਰ ਤੇਰੀ ਸਲਾਹ ਬਿਨ੍ਹਾਂ ਮੈਂ ਕੁਝ ਕਰਨਾ ਨਾ ਚਾਹਿਆ, ਤਾਂ ਜੋ ਤੇਰੀ ਇਹ ਭਲਾਈ ਮਜ਼ਬੂਰੀ ਨਾਲ ਨਹੀਂ, ਸਗੋਂ ਤੇਰੀ ਸਵੈ ਇੱਛਾ ਨਾਲ ਹੋਵੇ।","para tērī salāha binhāṁ maiṁ kujha karanā nā cāhiā, tāṁ jō tērī iha bhalāī mazabūrī nāla nahīṁ, sagōṁ tērī savai icchā nāla hōvē.",null],[1,15,"ਕਿਉਂ ਜੋ ਕੀ ਜਾਣੀਏ ਭਈ ਉਹ ਥੋੜ੍ਹਾ ਚਿਰ ਇਸ ਲਈ ਤੇਰੇ ਤੋਂ ਅਲੱਗ ਹੋਇਆ, ਤਾਂ ਕਿ ਉਹ ਸਦਾ ਤੇਰੇ ਨਜਦੀਕ ਰਹੇ।","kiuṁ jō kī jāṇīē bhaī uha thōṛhā cira isa laī tērē tōṁ alagga hōiā, tāṁ ki uha sadā tērē najadīka rahē.",null],[1,16,"ਅੱਗੇ ਨੂੰ ਦਾਸ ਵਾਂਗੂੰ ਨਹੀਂ ਸਗੋਂ ਦਾਸ ਨਾਲੋਂ ਚੰਗਾ, ਅਰਥਾਤ ਪਿਆਰੇ ਭਰਾ ਦੀ ਤਰ੍ਹਾਂ, ਖ਼ਾਸ ਕਰਕੇ ਮੇਰੇ ਲਈ, ਪਰ ਕਿੰਨ੍ਹਾਂ ਵਧੀਕ ਸਰੀਰ ਅਤੇ ਪ੍ਰਭੂ ਵਿੱਚ ਤੇਰਾ ਪਿਆਰਾ ਹੋਵੇਗਾ!","aggē nūṁ dāsa vāṁgūṁ nahīṁ sagōṁ dāsa nālōṁ caṁgā, arathāta piārē bharā dī tarhāṁ, k͟hāsa karakē mērē laī, para kinnhāṁ vadhīka sarīra atē prabhū vicca tērā piārā hōvēgā!",null],[1,17,"ਸੋ ਜੇ ਤੂੰ ਮੈਨੂੰ ਆਪਣਾ ਸਾਂਝੀ ਜਾਣਦਾ ਹੈਂ, ਤਾਂ ਜਿਵੇਂ ਮੈਨੂੰ ਕਬੂਲ ਕਰਦਾ ਹੈ ਤਿਵੇਂ ਉਹ ਨੂੰ ਕਬੂਲ ਕਰ।","sō jē tūṁ mainūṁ āpaṇā sāṁjhī jāṇadā haiṁ, tāṁ jivēṁ mainūṁ kabūla karadā hai tivēṁ uha nūṁ kabūla kara.",null],[1,18,"ਅਤੇ ਜੇ ਉਹ ਨੇ ਤੇਰਾ ਕੁਝ ਨੁਕਸਾਨ ਕੀਤਾ ਹੋਵੇ ਅਥਵਾ ਤੇਰਾ ਕੁਝ ਦੇਣਾ ਹੋਵੇ, ਤਾਂ ਉਹ ਨੂੰ ਮੇਰੇ ਨਾਮ ਲਿਖ ਲਵੀਂ।","atē jē uha nē tērā kujha nukasāna kītā hōvē athavā tērā kujha dēṇā hōvē, tāṁ uha nūṁ mērē nāma likha lavīṁ.",null],[1,19,"ਮੈਂ ਪੌਲੁਸ ਹਾਂ ਅਤੇ ਆਪਣੇ ਹੱਥੀਂ ਲਿਖਿਆ ਹੈ, ਮੈਂ ਹੀ ਭਰ ਦਿਆਂਗਾ ਜੋ ਮੈਂ ਤੈਨੂੰ ਇਹ ਨਾ ਆਖਾਂ ਭਈ ਮੇਰਾ ਕਰਜ਼ ਜੋ ਤੂੰ ਦੇਣਾ ਹੈ, ਸੋ ਤੂੰ ਆਪ ਹੀ ਹੈ!","maiṁ paulusa hāṁ atē āpaṇē hatthīṁ likhiā hai, maiṁ hī bhara diāṁgā jō maiṁ tainūṁ iha nā ākhāṁ bhaī mērā karaza jō tūṁ dēṇā hai, sō tūṁ āpa hī hai!",null],[1,20,"ਹਾਂ, ਭਰਾਵਾ, ਤੇਰੇ ਤੋਂ ਪ੍ਰਭੂ ਵਿੱਚ ਮੈਨੂੰ ਅਨੰਦ ਪ੍ਰਾਪਤ ਹੋਵੇ। ਮਸੀਹ ਵਿੱਚ ਮੇਰਾ ਦਿਲ ਤਰੋ ਤਾਜ਼ਾ ਕਰ।","hāṁ, bharāvā, tērē tōṁ prabhū vicca mainūṁ anaṁda prāpata hōvē. masīha vicca mērā dila tarō tāzā kara.",null],[1,21,"ਤੇਰੀ ਆਗਿਆਕਾਰੀ ਉੱਤੇ ਭਰੋਸਾ ਰੱਖ ਕੇ ਮੈਂ ਤੈਨੂੰ ਲਿਖਿਆ ਹੈ, ਕਿਉਂ ਜੋ ਮੈਂ ਜਾਣਦਾ ਹਾਂ ਭਈ ਜੋ ਕੁਝ ਮੈਂ ਆਖਦਾ ਹਾਂ ਤੂੰ ਉਸ ਤੋਂ ਵੱਧ ਕਰੇਂਗਾ।","tērī āgiākārī uttē bharōsā rakkha kē maiṁ tainūṁ likhiā hai, kiuṁ jō maiṁ jāṇadā hāṁ bhaī jō kujha maiṁ ākhadā hāṁ tūṁ usa tōṁ vaddha karēṁgā.",null],[1,22,"ਅਤੇ ਕੋਈ ਠਹਿਰਨ ਦਾ ਥਾਂ ਮੇਰੇ ਲਈ ਤਿਆਰ ਕਰ ਰੱਖ, ਕਿਉਂ ਜੋ ਮੈਨੂੰ ਆਸ ਹੈ ਕਿ ਤੁਹਾਡੀਆਂ ਪ੍ਰਾਰਥਨਾਵਾਂ ਦੇ ਦੁਆਰਾ ਤੁਹਾਨੂੰ ਬਖਸ਼ਿਆ ਜਾਂਵਾਂਗਾ।","atē kōī ṭhahirana dā thāṁ mērē laī tiāra kara rakkha, kiuṁ jō mainūṁ āsa hai ki tuhāḍīāṁ prārathanāvāṁ dē duārā tuhānūṁ bakhaśiā jāṁvāṁgā.",null],[1,23,"ਇਪਫ਼ਰਾਸ ਜਿਹੜਾ ਮਸੀਹ ਯਿਸੂ ਦੇ ਨਮਿੱਤ ਕੈਦ ਵਿੱਚ ਮੇਰਾ ਸਾਥੀ ਹੈ,","ipafarāsa jihaṛā masīha yisū dē namitta kaida vicca mērā sāthī hai,",null],[1,24,"ਅਤੇ ਮਰਕੁਸ, ਅਰਿਸਤਰਖੁਸ, ਦੇਮਾਸ ਅਤੇ ਲੂਕਾ ਜੋ ਮੇਰੇ ਨਾਲ ਦੇ ਸਹਿਕਰਮੀ ਤੇਰੀ ਸੁੱਖ-ਸਾਂਦ ਪੁੱਛਦੇ ਹਨ।","atē marakusa, arisatarakhusa, dēmāsa atē lūkā jō mērē nāla dē sahikaramī tērī sukkha-sāṁda pucchadē hana.",null],[1,25,"ਸਾਡੇ ਪ੍ਰਭੂ ਯਿਸੂ ਮਸੀਹ ਦੀ ਕਿਰਪਾ ਤੁਹਾਡੇ ਆਤਮਾ ਉੱਤੇ ਹੋਵੇ। ਆਮੀਨ।","sāḍē prabhū yisū masīha dī kirapā tuhāḍē ātamā uttē hōvē. āmīna.",null]],"bgc":[[1,1,"या चिट्ठी मुझ पौलुस, की ओड़ तै सै, जो मसीह यीशु का कैदी सै। हे फिलेमोन, मेरी अर बिश्वासी भाई तीमुथियुस की ओड़ तै तन्नै नमस्कार। तू म्हारा प्यारा मित्तर अर मसीह के काम करण म्ह म्हारा साझ्झीदार सै।","yā ciṭṭhī mujha paulusa, kī ōṛa tai sai, jō masīha yīśu kā kaidī sai. hē philēmōna, mērī ara biśvāsī bhāī tīmuthiyusa kī ōṛa tai tannai namaskāra. tū mhārā pyārā mittara ara masīha kē kāma karaṇa mha mhārā sājhjhīdāra sai.",null],[1,2,"मै भाण अफफिया, अर अरखिप्पुस ताहीं जो परमेसवर की सेवा एक सिपाही की तरियां करण लागरया सै, अर उस कलीसिया नै भी लिखूँ सूं, जो फिलेमोन के घर म्ह कठ्ठी हो सै।","mai bhāṇa aphaphiyā, ara arakhippusa tāhīṁ jō paramēsavara kī sēvā ēka sipāhī kī tariyāṁ karaṇa lāgarayā sai, ara usa kalīsiyā nai bhī likhūm̐ sūṁ, jō philēmōna kē ghara mha kaṭhṭhī hō sai.",null],[1,3,"मै प्रार्थना करुँ सूं, के म्हारे पिता परमेसवर अर प्रभु यीशु मसीह की ओड़ तै थमनै अनुग्रह अर शान्ति मिलती रहवै।","mai prārthanā karum̐ sūṁ, kē mhārē pitā paramēsavara ara prabhu yīśu masīha kī ōṛa tai thamanai anugraha ara śānti milatī rahavai.",null],[1,4,"मै जिब भी थारे खात्तर प्रार्थना करुँ सूं, तो मै सारी हाण थारे खात्तर परमेसवर का धन्यवाद करुँ सूं।","mai jiba bhī thārē khāttara prārthanā karum̐ sūṁ, tō mai sārī hāṇa thārē khāttara paramēsavara kā dhanyavāda karum̐ sūṁ.",null],[1,5,"मै प्रभु यीशु मसीह पै थारे बिश्वास अर परमेसवर के पवित्र माणसां के प्रति प्यार के बारें म्ह सुणदा रहूँ सूं।","mai prabhu yīśu masīha pai thārē biśvāsa ara paramēsavara kē pavitra māṇasāṁ kē prati pyāra kē bārēṁ mha suṇadā rahūm̐ sūṁ.",null],[1,6,"मै प्रार्थना करुँ सूं, के जो बिश्वासियाँ गैल थारी साझेदारी सै, उन भली चिज्जां के जाणण के जरिये जो परमेसवर नै म्हारे ताहीं दी सै, वा और घणी बढ़ती जावै। अर या म्हारे मसीह की महिमा खात्तर हो।","mai prārthanā karum̐ sūṁ, kē jō biśvāsiyām̐ gaila thārī sājhēdārī sai, una bhalī cijjāṁ kē jāṇaṇa kē jariyē jō paramēsavara nai mhārē tāhīṁ dī sai, vā aura ghaṇī baṛhatī jāvai. ara yā mhārē masīha kī mahimā khāttara hō.",null],[1,7,"क्यूँके हे बिश्वासी भाईयो, मै भोत खुश सूं, अर मेरे प्रति थारे प्यार तै मै घणा उत्साहित सूं, अर इस कारण पवित्र माणसां नै घणी खुशी मिली सै।","kyūm̐kē hē biśvāsī bhāīyō, mai bhōta khuśa sūṁ, ara mērē prati thārē pyāra tai mai ghaṇā utsāhita sūṁ, ara isa kāraṇa pavitra māṇasāṁ nai ghaṇī khuśī milī sai.",null],[1,8,"जो हक मेरे ताहीं मसीह नै दिया सै, उसकी बजह तै मै थमनै हुकम दे सकूँ सूं, के थमनै के करण की जरूरत सै, पर मै इसा कोनी करुँ, मै पौलुस, बुजुर्ग माणस होण के नाते अर मसीह यीशु का कैदी होण के कारण थारे तै प्यार तै बिनती करुँ सूं।","jō haka mērē tāhīṁ masīha nai diyā sai, usakī bajaha tai mai thamanai hukama dē sakūm̐ sūṁ, kē thamanai kē karaṇa kī jarūrata sai, para mai isā kōnī karum̐, mai paulusa, bujurga māṇasa hōṇa kē nātē ara masīha yīśu kā kaidī hōṇa kē kāraṇa thārē tai pyāra tai binatī karum̐ sūṁ.",9],[1,10,"मेरी बिनती या सै के उनेसिमुस जो मेरै बाळक की तरियां सै, वो मसीह म्ह मेरा आत्मिक बेट्टा जिब बण्या जिब मै कैद म्ह था, थम उसपै दया करियो।","mērī binatī yā sai kē unēsimusa jō mērai bāḷaka kī tariyāṁ sai, vō masīha mha mērā ātmika bēṭṭā jiba baṇyā jiba mai kaida mha thā, thama usapai dayā kariyō.",null],[1,11,"वो तो पैहला तेरे किमे काम का ना था, पर इब तेरे अर मेरै दोनुआ कै खात्तर बड़े काम का सै।","vō tō paihalā tērē kimē kāma kā nā thā, para iba tērē ara mērai dōnuā kai khāttara baṛē kāma kā sai.",null],[1,12,"उस्से नै यानी जो मेरै दिल का टुकड़ा सै, मै तेरे धोरै भेज्जू सूं।","ussē nai yānī jō mērai dila kā ṭukaṛā sai, mai tērē dhōrai bhējjū sūṁ.",null],[1,13,"उसनै मै अपणे ए धोरै राखणा चाहूँ था, ताके वो तेरी जगहां मेरी मदद कर सकै, जिब के मै मसीह का सुसमाचार सुणाण कै खात्तर कैद म्ह सूं।","usanai mai apaṇē ē dhōrai rākhaṇā cāhūm̐ thā, tākē vō tērī jagahāṁ mērī madada kara sakai, jiba kē mai masīha kā susamācāra suṇāṇa kai khāttara kaida mha sūṁ.",null],[1,14,"पर मन्नै तेरी इच्छा बगैर कुछ भी न्ही करणा चाह्या। मै चाहूँ था के तू मेरी मदद मजबूरी म्ह न्ही पर खुद की इच्छा तै खुशी तै करै।","para mannai tērī icchā bagaira kucha bhī nhī karaṇā cāhyā. mai cāhūm̐ thā kē tū mērī madada majabūrī mha nhī para khuda kī icchā tai khuśī tai karai.",null],[1,15,"हो सकै सै के परमेसवर नै उनेसिमुस ताहीं, तेरे तै इस करकै थोड़े बखत खात्तर दूर जाण का मौक्का दिया, ताके वो मसीह पै बिश्वास कर सकै, अर उसकी बजह तै तू सदा खात्तर उसनै पा लेवै।","hō sakai sai kē paramēsavara nai unēsimusa tāhīṁ, tērē tai isa karakai thōṛē bakhata khāttara dūra jāṇa kā maukkā diyā, tākē vō masīha pai biśvāsa kara sakai, ara usakī bajaha tai tū sadā khāttara usanai pā lēvai.",null],[1,16,"पर इब वो तेरा दास ए कोनी बल्के दास तै भी बढ़कै, यानी बिश्वासी भाई सै। मै उसतै भोत प्यार करुँ सूं, पर इब तू मेरे तै भी ज्यादा उसतै प्यार कर, दास की तरियां न्ही, पर बिश्वासी भाई की तरियां।","para iba vō tērā dāsa ē kōnī balkē dāsa tai bhī baṛhakai, yānī biśvāsī bhāī sai. mai usatai bhōta pyāra karum̐ sūṁ, para iba tū mērē tai bhī jyādā usatai pyāra kara, dāsa kī tariyāṁ nhī, para biśvāsī bhāī kī tariyāṁ.",null],[1,17,"इस करकै जै तू मन्नै अपणा साझीदार समझै सै, तो उनेसिमुस जिब थारे धोरै बोहड़ के आवैगा, तो उसनै प्यार तै अपणा लियो, जिस तरियां थम मन्नै अपणाओ सों।","isa karakai jai tū mannai apaṇā sājhīdāra samajhai sai, tō unēsimusa jiba thārē dhōrai bōhaṛa kē āvaigā, tō usanai pyāra tai apaṇā liyō, jisa tariyāṁ thama mannai apaṇāō sōṁ.",null],[1,18,"जै उसनै तेरा कुछ भी नुकसान करया सै, या उसपै तेरा कुछ कर्ज सै, तो आकै दे दियुँगा।","jai usanai tērā kucha bhī nukasāna karayā sai, yā usapai tērā kucha karja sai, tō ākai dē diyum̐gā.",null],[1,19,"मै पौलुस अपणे हाथ तै लिखूँ सूं, के उसका कर्जा मै आप दे दियुँगा, तू खुद जाणै सै, जै मै तेरी मदद न्ही करदा, तो तन्नै नई जिन्दगी न्ही मिलती, इस करकै तू जिन्दगी भर मेरा कर्जदार सै।","mai paulusa apaṇē hātha tai likhūm̐ sūṁ, kē usakā karjā mai āpa dē diyum̐gā, tū khuda jāṇai sai, jai mai tērī madada nhī karadā, tō tannai naī jindagī nhī milatī, isa karakai tū jindagī bhara mērā karjadāra sai.",null],[1,20,"हे मेरे प्यारे भाई, मेरे खात्तर योए कर क्यूँके हम बिश्वासी भाई सां, अर तेरे इसा करण तै मै मसीह म्ह उत्साहित हो जाऊँगा।","hē mērē pyārē bhāī, mērē khāttara yōē kara kyūm̐kē hama biśvāsī bhāī sāṁ, ara tērē isā karaṇa tai mai masīha mha utsāhita hō jāūm̐gā.",null],[1,21,"मै तेरे पै भरोस्सा करकै तेरे तै लिखूँ सूं, अर या जाणु सूं के जो कुछ मै कहूँ सूं, तू उसतै घणा बढ़कै करैगा।","mai tērē pai bharōssā karakai tērē tai likhūm̐ sūṁ, ara yā jāṇu sūṁ kē jō kucha mai kahūm̐ sūṁ, tū usatai ghaṇā baṛhakai karaigā.",null],[1,22,"अर या भी कै मेरै खात्तर रुकण की जगहां तैयार राक्खै। मन्नै उम्मीद सै, के परमेसवर थारी प्रार्थनायां का जवाब देवैगा, अर मै थारे धोरै आकै थमनै देख पाऊँगा।","ara yā bhī kai mērai khāttara rukaṇa kī jagahāṁ taiyāra rākkhai. mannai ummīda sai, kē paramēsavara thārī prārthanāyāṁ kā javāba dēvaigā, ara mai thārē dhōrai ākai thamanai dēkha pāūm̐gā.",null],[1,23,"इपफ्रास, जो मेरै गैल जेळ म्ह कैद सै, क्यूँके वो यीशु मसीह की सेवा करै सै थारे ताहीं नमस्कार कहवै सै।","ipaphrāsa, jō mērai gaila jēḷa mha kaida sai, kyūm̐kē vō yīśu masīha kī sēvā karai sai thārē tāhīṁ namaskāra kahavai sai.",null],[1,24,"अर मरकुस, अरिस्तर्खुस, देमास अर लूका जो मेरे गैल परमेसवर का काम करणीये सै, इनका भी तेरे ताहीं नमस्कार।","ara marakusa, aristarkhusa, dēmāsa ara lūkā jō mērē gaila paramēsavara kā kāma karaṇīyē sai, inakā bhī tērē tāhīṁ namaskāra.",null],[1,25,"मै प्रार्थना करुँ सूं, के म्हारे प्रभु यीशु मसीह का अनुग्रह थारे साथ होंदा रहवै। आमीन।","mai prārthanā karum̐ sūṁ, kē mhārē prabhu yīśu masīha kā anugraha thārē sātha hōṁdā rahavai. āmīna.",null]],"urd":[[1,1,"पौलुस की तरफ़ से जो मसीह ईसा का क़ैदी है, और भाई तीमुथियुस की तरफ़ से अपने 'अज़ीज़ और हम ख़िदमत फिलेमोन,","paulusa kī tarafa sē jō masīha īsā kā qaidī hai, aura bhāī tīmuthiyusa kī tarafa sē apanē 'azīza aura hama k͟hidamata philēmōna,",null],[1,2,"और बहन अफ़िया, और अपने हम सफ़र आर्ख़िप्पुस और फिलेमोन के घर की कलीसिया के नाम ख़त:","aura bahana afiyā, aura apanē hama safara ārk͟hippusa aura philēmōna kē ghara kī kalīsiyā kē nāma k͟hata:",null],[1,3,"फ़ज़ल और इत्मीनान हमारे बाप ख़ुदा और ख़ुदावन्द 'ईसा मसीह की तरफ़ से तुम्हें हासिल होता रहे।","fazala aura itmīnāna hamārē bāpa k͟hudā aura k͟hudāvanda 'īsā masīha kī tarafa sē tumhēṁ hāsila hōtā rahē.",null],[1,4,"मैं तेरी उस मुहब्बत का और ईमान का हाल सुन कर, जो सब मुक़द्दसों के साथ और ख़ुदावन्द ईसा पर है'","maiṁ tērī usa muhabbata kā aura īmāna kā hāla suna kara, jō saba muqaddasōṁ kē sātha aura k͟hudāvanda īsā para hai'",null],[1,5,"हमेशा अपने ख़ुदा का शुक्र करता हूँ, और अपनी दु'आओं में तुझे याद करता हूँ।","hamēśā apanē k͟hudā kā śukra karatā hūm̐, aura apanī du'āōṁ mēṁ tujhē yāda karatā hūm̐.",null],[1,6,"ताकि तेरे ईमान की शिराकत तुम्हारी हर ख़ूबी की पहचान में मसीह के वास्ते मु' अस्सिर हो।","tāki tērē īmāna kī śirākata tumhārī hara k͟hūbī kī pahacāna mēṁ masīha kē vāstē mu' assira hō.",null],[1,7,"क्यूँकि ऐ भाई! मुझे तेरी मुहब्बत से बहुत ख़ुशी और तसल्ली हुई, इसलिए कि तेरी वजह से मुक़द्दसों के दिल ताज़ा हुए हैं।","kyūm̐ki ai bhāī! mujhē tērī muhabbata sē bahuta k͟huśī aura tasallī huī, isaliē ki tērī vajaha sē muqaddasōṁ kē dila tāzā huē haiṁ.",null],[1,8,"पस अगरचे मुझे मसीह में बड़ी दिलेरी तो है कि तुझे मुनासिब हुक्म दूँ।","pasa agaracē mujhē masīha mēṁ baṛī dilērī tō hai ki tujhē munāsiba hukma dūm̐.",null],[1,9,"मगर मुझे ये ज़्यादा पसन्द है कि मैं बूढ़ा पौलुस, बल्कि इस वक़्त मसीह 'ईसा का क़ैदी भी होकर मुहब्बत की राह से इल्तिमास करूँ।","magara mujhē yē zyādā pasanda hai ki maiṁ būṛhā paulusa, balki isa vaqta masīha 'īsā kā qaidī bhī hōkara muhabbata kī rāha sē iltimāsa karūm̐.",null],[1,10,"सो अपने फ़र्ज़न्द उनेसिमुस के बारे में जो क़ैद की हालत में मुझ से पैदा हुआ, तुझसे इल्तिमास करता हूँ।","sō apanē farzanda unēsimusa kē bārē mēṁ jō qaida kī hālata mēṁ mujha sē paidā huā, tujhasē iltimāsa karatā hūm̐.",null],[1,11,"पहले तो तेरे कुछ काम का ना था मगर अब तेरे और मेरे दोनों के काम का है।","pahalē tō tērē kucha kāma kā nā thā magara aba tērē aura mērē dōnōṁ kē kāma kā hai.",null],[1,12,"ख़ुद उसी को या'नी अपने कलेजे के टुकड़े को, मैने तेरे पास वापस भेजा है।","k͟huda usī kō yā'nī apanē kalējē kē ṭukaṛē kō, mainē tērē pāsa vāpasa bhējā hai.",null],[1,13,"उसको मैं अपने ही पास रखना चाहता था, ताकि तेरी तरफ़ से इस क़ैद में जो ख़ुशख़बरी के ज़रिए है मेरी ख़िदमत करे।","usakō maiṁ apanē hī pāsa rakhanā cāhatā thā, tāki tērī tarafa sē isa qaida mēṁ jō k͟huśak͟habarī kē zariē hai mērī k͟hidamata karē.",null],[1,14,"लेकिन तेरी मर्ज़ी के बग़ैर में ने कुछ करना न चाहा, ताकि तेरे नेक काम लाचारी से नहीं बल्कि ख़ुशी से हों।","lēkina tērī marzī kē baġaira mēṁ nē kucha karanā na cāhā, tāki tērē nēka kāma lācārī sē nahīṁ balki k͟huśī sē hōṁ.",null],[1,15,"क्यूँकि मुम्किन है कि वो तुझ से इसलिए थोड़ी देर के वास्ते जुदा हुआ हो कि हमेशा तेरे पास रहे।","kyūm̐ki mumkina hai ki vō tujha sē isaliē thōṛī dēra kē vāstē judā huā hō ki hamēśā tērē pāsa rahē.",null],[1,16,"मगर अब से ग़ुलाम की तरह नहीं बल्कि ग़ुलाम से बेहतर होकर या'नी ऐसे भाई की तरह रहे जो जिस्म में भी और ख़ुदावन्द में भी मेरा निहायत 'अज़ीज़ हो और तेरा इससे भी कही ज़्यादा।","magara aba sē ġulāma kī taraha nahīṁ balki ġulāma sē bēhatara hōkara yā'nī aisē bhāī kī taraha rahē jō jisma mēṁ bhī aura k͟hudāvanda mēṁ bhī mērā nihāyata 'azīza hō aura tērā isasē bhī kahī zyādā.",null],[1,17,"पस अगर तू मुझे शरीक जानता है, तो उसे इस तरह क़ुबूल करना जिस तरह मुझे।","pasa agara tū mujhē śarīka jānatā hai, tō usē isa taraha qubūla karanā jisa taraha mujhē.",null],[1,18,"और अगर उस ने तेरा कुछ नुक़्सान किया है, या उस पर तेरा कुछ आता है, तो उसे मेरे नाम से लिख ले।","aura agara usa nē tērā kucha nuqsāna kiyā hai, yā usa para tērā kucha ātā hai, tō usē mērē nāma sē likha lē.",null],[1,19,"मैं पौलुस अपने हाथ से लिखता हूँ कि ख़ुद अदा करूँगा, इसके कहने की कुछ ज़रूरत नहीं कि मेरा क़र्ज़ जो तुझ पर है वो तू ख़ुद है","maiṁ paulusa apanē hātha sē likhatā hūm̐ ki k͟huda adā karūm̐gā, isakē kahanē kī kucha zarūrata nahīṁ ki mērā qarza jō tujha para hai vō tū k͟huda hai",null],[1,20,"ऐ भाई! मैं चाहता हूँ कि मुझे तेरी तरफ़ से ख़ुदावन्द में ख़ुशी हासिल हो। मसीह में मेरे दिल को ताज़ा कर।","ai bhāī! maiṁ cāhatā hūm̐ ki mujhē tērī tarafa sē k͟hudāvanda mēṁ k͟huśī hāsila hō. masīha mēṁ mērē dila kō tāzā kara.",null],[1,21,"मैं तेरी फ़रमाँबरदारी का यक़ीन करके तुझे लिखता हूँ, और जानता हूँ कि जो कुछ मैं कहता हूँ, तू उस से भी ज़्यादा करेगा।","maiṁ tērī faramām̐baradārī kā yaqīna karakē tujhē likhatā hūm̐, aura jānatā hūm̐ ki jō kucha maiṁ kahatā hūm̐, tū usa sē bhī zyādā karēgā.",null],[1,22,"इसके सिवा मेरे लिए ठहरने की जगह तैयार कर, क्यूँकि मुझे उम्मीद है कि मैं तुम्हारी दु' आओं के वसीले से तुम्हें बख़्शा जाऊँगा।","isakē sivā mērē liē ṭhaharanē kī jagaha taiyāra kara, kyūm̐ki mujhē ummīda hai ki maiṁ tumhārī du' āōṁ kē vasīlē sē tumhēṁ bak͟hśā jāūm̐gā.",null],[1,23,"इपफ़्रास जो मसीह ईसा में मेरे साथ क़ैद है,","ipafrāsa jō masīha īsā mēṁ mērē sātha qaida hai,",null],[1,24,"और मरकुस और अरिस्तरख़ुस और दोमास और लुक़ा, जो मेरे हम ख़िदमत हैं तुझे सलाम कहते है।","aura marakusa aura aristarak͟husa aura dōmāsa aura luqā, jō mērē hama k͟hidamata haiṁ tujhē salāma kahatē hai.",null],[1,25,"हमारे ख़ुदावन्द ईसा मसीह का फ़ज़ल तुम्हारी रूह पर होता रहे। आमीन।","hamārē k͟hudāvanda īsā masīha kā fazala tumhārī rūha para hōtā rahē. āmīna.",null]],"dgo":[[1,1,"पोलुस थमा जेहडा मसीह यीशु दा कैदी ऐ, अते प्रा तीमुथियुस थमा साहडे प्यारे सहकर्मी फिलेमोन,","pōlusa thamā jēhaḍā masīha yīśu dā kaidī ai, atē prā tīmuthiyusa thamā sāhaḍē pyārē sahakarmī philēmōna,",null],[1,2,"अते पैंन अफफिया, अते साहडे साथी योद्धा अरखिप्पुस अते फिलेमोन दे कर दी कलीसिया दे नां:","atē paiṁna aphaphiyā, atē sāhaḍē sāthī yōddhā arakhippusa atē philēmōna dē kara dī kalīsiyā dē nāṁ:",null],[1,3,"साहडे प्यो परमात्मा अते प्रभु यीशु मसीह थमा क्रपा अते शान्ति तुसें मिलदी रबे ।","sāhaḍē pyō paramātmā atē prabhu yīśu masīha thamā krapā atē śānti tusēṁ miladī rabē .",null],[1,4,"आऊ हमेशा परमात्मा दा सुकर करना ऐ, अते अपनी प्रार्थना बिच तुगी याद करना ऐ,","āū hamēśā paramātmā dā sukara karanā ai, atē apanī prārthanā bica tugī yāda karanā ai,",null],[1,5,"कीहके आऊ अतेरे उस्स लाड अते परोसा दी चर्चा सुनना ऐ, जेकी सारें पवित्र लोकें कन्ने अते प्रभु यीशु उप्पर ऐ ।","kīhakē āū atērē ussa lāḍa atē parōsā dī carcā sunanā ai, jēkī sārēṁ pavitra lōkēṁ kannē atē prabhu yīśu uppara ai .",null],[1,6,"आऊ प्रार्थना करना ऐ के परोसा च अतेरा शामल ओना, थुआढी सारी पलाई दी पनछान बिच, मसीह अस अते ताकत आला ओए ।","āū prārthanā karanā ai kē parōsā ca atērā śāmala ōnā, thuāḍhī sārī palāī dī panachāna bica, masīha asa atē tākata ālā ōē .",null],[1,7,"कीहके ए प्रा, मीकी अतेरे लाड कन्ने मता खुशी अते शान्ति मिली ऐ, इसे अस अते के अतेरे रहें पवित्र लोकें दे मन अरे परे ओई गेदे न ।","kīhakē ē prā, mīkī atērē lāḍa kannē matā khuśī atē śānti milī ai, isē asa atē kē atērē rahēṁ pavitra lōkēṁ dē mana arē parē ōī gēdē na .",null],[1,8,"इसे अस अते जेकरचे मीकी मसीह च मती हिम्मत ऐ के जेकी गल्ल ठीक ऐ, उस्स दी उक्म तुगी दियां ।","isē asa atē jēkaracē mīkī masīha ca matī himmata ai kē jēkī galla ṭhīka ai, ussa dī ukma tugī diyāṁ .",null],[1,9,"तां भी मीकी बुड्डे पोलुस गी जेहडा हूंन मसीह यीशु अस अते कैदी ऐ, ए अते भी पला जानया के लाड कन्ने बिनती करां ।","tāṁ bhī mīkī buḍḍē pōlusa gī jēhaḍā hūṁna masīha yīśu asa atē kaidī ai, ē atē bhī palā jānayā kē lāḍa kannē binatī karāṁ .",null],[1,10,"आऊ अपने बच्चे उनेसिमुस अस अते, जेहडा मेरे अस अते मेरी कैद च जम्मा ऐ, अतेरे कन्ने बिनती करना ऐ ।","āū apanē baccē unēsimusa asa atē, jēhaḍā mērē asa atē mērī kaida ca jammā ai, atērē kannē binatī karanā ai .",null],[1,11,"ओह अते पैलैं अतेरे किश कम्म दा नेई हा, लेकन हूंन अतेरे अते मेरे दोनो दे मअते कम्म दा ऐ ।","ōha atē pailaiṁ atērē kiśa kamma dā nēī hā, lēkana hūṁna atērē atē mērē dōnō dē maatē kamma dā ai .",null],[1,12,"उसे गी मतलब जेहडा मेरे दिल दा टुकड़ा ऐ, आऊ अतेरे कोल बापस करी दीता ऐ ।","usē gī matalaba jēhaḍā mērē dila dā ṭukaṛā ai, āū atērē kōla bāpasa karī dītā ai .",null],[1,13,"उसे आऊ अपने गै कोल रखना चांदा हा के ओह अतेरी अते थमा इस कैद च जेकी सनेया दे कारन ऐ, मेरी सेवा करै ।","usē āū apanē gai kōla rakhanā cāṁdā hā kē ōha atērī atē thamā isa kaida ca jēkī sanēyā dē kārana ai, mērī sēvā karai .",null],[1,14,"लेकन आऊ अतेरी मरजी बगैर किश भी करना नेई चाया, के अतेरी ए कृपा दबाब कन्ने नेई लेकन आनद कन्ने ओए ।","lēkana āū atērī marajī bagaira kiśa bhī karanā nēī cāyā, kē atērī ē kr̥pā dabāba kannē nēī lēkana ānada kannē ōē .",null],[1,15,"कीहके के जाने ओह अतेरे थमा किश धयारे अस अते इसे कारन लाग ओया के हमेशा अतेरे कोल रबे ।","kīhakē kē jānē ōha atērē thamā kiśa dhayārē asa atē isē kārana lāga ōyā kē hamēśā atērē kōla rabē .",null],[1,16,"लेकन हूंन थमा दास जेया नेई बरना दास थमा भी उत्तम, मतलब प्रा दे लेखा रबे, जेहडा मेरा अते ख़ास प्यारा अते ऐ गै, लेकन हूंन जीद च भी अते प्रभु च भी, अतेरा भी ख़ास प्यारा ओए ।","lēkana hūṁna thamā dāsa jēyā nēī baranā dāsa thamā bhī uttama, matalaba prā dē lēkhā rabē, jēhaḍā mērā atē k͟hāsa pyārā atē ai gai, lēkana hūṁna jīda ca bhī atē prabhu ca bhī, atērā bhī k͟hāsa pyārā ōē .",null],[1,17,"इस अस अते जे तू मीकी अपना शामल समझना ऐ, अते उसे इस चाल्ली ग्रहण कर जिय्यां मीकी ।","isa asa atē jē tū mīkī apanā śāmala samajhanā ai, atē usē isa cāllī grahaṇa kara jiyyāṁ mīkī .",null],[1,18,"जे उस्स ने अतेरा किश नुक्सान कित्ता ऐ, जां उस्स उप्पर अतेरा किश आंदा ऐ, अते मेरे नां उप्पर लिखी लै ।","jē ussa nē atērā kiśa nuksāna kittā ai, jāṁ ussa uppara atērā kiśa āṁdā ai, atē mērē nāṁ uppara likhī lai .",null],[1,19,"आऊ पोलुस अपने हत्थें दा लिखना ऐ के आऊ अप्पुं परी देगा; अते इस दे आखने दी कोई जरूरत नेइ के मेरा कर्जा जेहडा अतेरे उप्पर ऐ ओह तू गै ऐं ।","āū pōlusa apanē hatthēṁ dā likhanā ai kē āū appuṁ parī dēgā; atē isa dē ākhanē dī kōī jarūrata nēi kē mērā karjā jēhaḍā atērē uppara ai ōha tū gai aiṁ .",null],[1,20,"ए प्रा, ए खुशी मिगी प्रभु च अतेरे थमा मिले । मसीह च मेरे जी गी अरा परा करी दे ।","ē prā, ē khuśī migī prabhu ca atērē thamā milē . masīha ca mērē jī gī arā parā karī dē .",null],[1,21,"आऊ अतेरे उक्म कारी दा परोसा रखियै तुगी लिखना ऐ, अते ए जानना ऐं के हो किश आऊ आखना ऐं, तू उस्स थमा कई बद करंगा ।","āū atērē ukma kārī dā parōsā rakhiyai tugī likhanā ai, atē ē jānanā aiṁ kē hō kiśa āū ākhanā aiṁ, tū ussa thamā kaī bada karaṁgā .",null],[1,22,"अते ए भी के मेरे अस अते ठअर ने दी जगह अतेयार रख । मीकी अस ऐ के अतेरी प्रार्थना दे रहें आऊ तुसें देई दीता जाह्गा ।","atē ē bhī kē mērē asa atē ṭhaara nē dī jagaha atēyāra rakha . mīkī asa ai kē atērī prārthanā dē rahēṁ āū tusēṁ dēī dītā jāhgā .",null],[1,23,"इपफ्रास, जेहडा मसीह यीशु च मेरे कन्ने कैदी ऐ |","ipaphrāsa, jēhaḍā masīha yīśu ca mērē kannē kaidī ai |",null],[1,24,"अते मरकुस अते अरिस्तर्खुस अते देमास अते लुका जेके मेरे सहकर्मी न, इंदा तुेसेग़ी नमस्कार ।","atē marakusa atē aristarkhusa atē dēmāsa atē lukā jēkē mērē sahakarmī na, iṁdā tuēsēġī namaskāra .",null],[1,25,"साहडे प्रभु यीशु मसीह दा क्रपा थुआढी आत्मा उप्पर ओंदा रबे । आमीन ।","sāhaḍē prabhu yīśu masīha dā krapā thuāḍhī ātmā uppara ōṁdā rabē . āmīna .",null]],"xnr":[[1,1,"पौलुसे दे पास्से ते जेह्ड़ा मसीह यीशु दा कैदी ऐ, कने भाऊये तीमुथियुस दे पास्से ते अहां दे प्यारे सेहकर्मी फिलेमोन,","paulusē dē pāssē tē jēhṛā masīha yīśu dā kaidī ai, kanē bhāūyē tīmuthiyusa dē pāssē tē ahāṁ dē pyārē sēhakarmī philēmōna,",null],[1,2,"कने बैहण अफफिया, कने अहां दे साथी योद्धा अरखिप्पुस कने फिलेमोन दे घरे दी कलीसिया दे नां:","kanē baihaṇa aphaphiyā, kanē ahāṁ dē sāthī yōddhā arakhippusa kanē philēmōna dē gharē dī kalīsiyā dē nāṁ:",null],[1,3,"अहां दे पिता परमात्में कने प्रभु यीशु मसीह दे पास्से ते अनुग्रह कने शांति तुहां जो मिलदी रैंह् ।","ahāṁ dē pitā paramātmēṁ kanē prabhu yīśu masīha dē pāssē tē anugraha kanē śāṁti tuhāṁ jō miladī raiṁh .",null],[1,4,"मैं सदा परमात्में दा धन्यवाद करदा ऐ, कने अपणी प्रार्थनां च भी तिज्जो याद करदा ऐ,","maiṁ sadā paramātmēṁ dā dhanyavāda karadā ai, kanē apaṇī prārthanāṁ ca bhī tijjō yāda karadā ai,",null],[1,5,"क्जोकि मैं तेरे तिस प्यारे कने वसुआसे दी चर्चा सुणदा ऐ, जेह्ड़ा सारे पवित्र लोकां सौगी कने प्रभु यीशु पर ऐ ।","kjōki maiṁ tērē tisa pyārē kanē vasuāsē dī carcā suṇadā ai, jēhṛā sārē pavitra lōkāṁ saugī kanē prabhu yīśu para ai .",null],[1,6,"मैं प्रार्थना करदा ऐ कि वसुआस च तेरा सेहभागी होणां, तुहां दी सारी भलाई दी पणछैणां च, मसीह तांई असरदार होयें ।","maiṁ prārthanā karadā ai ki vasuāsa ca tērā sēhabhāgī hōṇāṁ, tuhāṁ dī sārī bhalāī dī paṇachaiṇāṁ ca, masīha tāṁī asaradāra hōyēṁ .",null],[1,7,"क्जोकि हे भाऊ, तिज्जो तेरे प्यारे ते मती सारी खुशी कने शांति मिलियो ऐ, इसतांई कि तेरिया बजाह ते पवित्र लोकां दे मन हरे भरे होई गैयो हन ।","kjōki hē bhāū, tijjō tērē pyārē tē matī sārī khuśī kanē śāṁti miliyō ai, isatāṁī ki tēriyā bajāha tē pavitra lōkāṁ dē mana harē bharē hōī gaiyō hana .",null],[1,8,"इसतांई जे मिन्जो मसीह च बड़ी हिम्मत ऐ कि जेह्ड़ी गल्ल ठीक ऐ, तिसादा हुक्म तिज्जो दैं,","isatāṁī jē minjō masīha ca baṛī himmata ai ki jēhṛī galla ṭhīka ai, tisādā hukma tijjō daiṁ,",null],[1,9,"भिरी भी मिन्जो बूढे पौलुसे जो जेह्ड़ा हुण मसीह यीशु तांई कैदी ऐ, एह होर भी खरा लग्गा कि प्यारे नैं विणती करें ।","bhirī bhī minjō būḍhē paulusē jō jēhṛā huṇa masīha yīśu tāṁī kaidī ai, ēha hōra bhī kharā laggā ki pyārē naiṁ viṇatī karēṁ .",null],[1,10,"मैं अपणे बच्चे उनेसिमुस तांई, जेह्ड़ा मिन्जो ते मेरिया कैदा च जम्मेया ऐ, तिज्जो नैं विणती करदा ऐ ।","maiṁ apaṇē baccē unēsimusa tāṁī, jēhṛā minjō tē mēriyā kaidā ca jammēyā ai, tijjō naiṁ viṇatī karadā ai .",null],[1,11,"सैह तां पैहले तेरे कुच्छ कम्म दा नी था, अपर हुण तेरे कने मेरे दूनी दा बड़े कम्मे दा ऐ ।","saiha tāṁ paihalē tērē kuccha kamma dā nī thā, apara huṇa tērē kanē mērē dūnī dā baṛē kammē dā ai .",null],[1,12,"तिस जो जे जेह्ड़ा मेरे मने दा टुकड़ा ऐ, मैं तिज्जो अल्ल वापस करी दित्ता ऐ ।","tisa jō jē jēhṛā mērē manē dā ṭukaṛā ai, maiṁ tijjō alla vāpasa karī dittā ai .",null],[1,13,"तिसियो मैं अपणे अल्ल ई रखणां चाहंदा था कि सैह तेरे पास्से ते इसा कैदा च जेह्ड़ा सुसमाचार दिया बजाह ते ऐ, मेरी सेवा करें ।","tisiyō maiṁ apaṇē alla ī rakhaṇāṁ cāhaṁdā thā ki saiha tērē pāssē tē isā kaidā ca jēhṛā susamācāra diyā bajāha tē ai, mērī sēvā karēṁ .",null],[1,14,"अपर मैं तेरी इच्छा बगैर कुच्छ भी करणां नी चाहंदा, कि तेरी एह कृपा दबाबे नैं नी अपर खुशिया नैं होयें ।","apara maiṁ tērī icchā bagaira kuccha bhī karaṇāṁ nī cāhaṁdā, ki tērī ēha kr̥pā dabābē naiṁ nī apara khuśiyā naiṁ hōyēṁ .",null],[1,15,"क्जोकि क्या पता सैह तिज्जो ते कुच्छ दिन तिकर इसा बजाह ते दूर होया कि हमेशा तिज्जो अल्ल रैंह् ।","kjōki kyā patā saiha tijjō tē kuccha dina tikara isā bajāha tē dūra hōyā ki hamēśā tijjō alla raiṁh .",null],[1,16,"अपर हुण दासे साइआं नी अपर दासे ते भी उत्तम, मतलब भाऊये साइआं रैंह्, जेह्ड़ा मेरा तां खास प्यारा ऐ ई अपर हुण शरीरे च कने प्रभु च भी, तेरा भी खास प्यारा होयें ।","apara huṇa dāsē sāiāṁ nī apara dāsē tē bhī uttama, matalaba bhāūyē sāiāṁ raiṁh, jēhṛā mērā tāṁ khāsa pyārā ai ī apara huṇa śarīrē ca kanē prabhu ca bhī, tērā bhī khāsa pyārā hōyēṁ .",null],[1,17,"जे तू मिन्जो अपणां सेहभागी समझदा ऐ, तां तिसियो इस तरांह ग्रहण कर जिआं मिन्जो ।","jē tū minjō apaṇāṁ sēhabhāgī samajhadā ai, tāṁ tisiyō isa tarāṁha grahaṇa kara jiāṁ minjō .",null],[1,18,"जे तिन्हीं तेरा कुच्छ नकसान कित्ता ऐ, या तिन्हीं तेरा कुच्छ देणा तां मेरे खाते च लिख लै ।","jē tinhīṁ tērā kuccha nakasāna kittā ai, yā tinhīṁ tērā kuccha dēṇā tāṁ mērē khātē ca likha lai .",null],[1,19,"मैं पौलुस अपणे हत्थे नैं लिखदा कि मैं अप्पु भरी दिंगा; कने इस दे ग्लाणे दी कुच्छ जरूरत नी कि मेरा कर्ज जेह्ड़ा तिज्जो पर ऐ सैह तू ई ऐ ।","maiṁ paulusa apaṇē hatthē naiṁ likhadā ki maiṁ appu bharī diṁgā; kanē isa dē glāṇē dī kuccha jarūrata nī ki mērā karja jēhṛā tijjō para ai saiha tū ī ai .",null],[1,20,"हे भाऊ, एह खुशी मिन्जो प्रभु च तेरिया तरफा ते मिलें । मसीह च मेरे दिले जो हरा भरा करी दे ।","hē bhāū, ēha khuśī minjō prabhu ca tēriyā taraphā tē milēṁ . masīha ca mērē dilē jō harā bharā karī dē .",null],[1,21,"मैं तेरे आज्ञाकारी होणे दा भरोसा रखी नैं तिज्जो लिखदा ऐ, कने एह जाणदा ऐ कि जेह्ड़ा कुच्छ मैं ग्लांदा, तू तिसते केंह बधी नैं करगा ।","maiṁ tērē ājñākārī hōṇē dā bharōsā rakhī naiṁ tijjō likhadā ai, kanē ēha jāṇadā ai ki jēhṛā kuccha maiṁ glāṁdā, tū tisatē kēṁha badhī naiṁ karagā .",null],[1,22,"कने एह भी कि मिन्जो तांई ठेहरणे दी जगाह त्यार रख । मिन्जो आशा ऐ कि तुहां प्रार्थना दिया बजाह ते मैं तुहां जो दैई दित्ता जांगा ।","kanē ēha bhī ki minjō tāṁī ṭhēharaṇē dī jagāha tyāra rakha . minjō āśā ai ki tuhāṁ prārthanā diyā bajāha tē maiṁ tuhāṁ jō daiī dittā jāṁgā .",null],[1,23,"इपफ्रास जेह्ड़ा मसीह यीशु च मिन्जो सौगी कैदी ऐ,","ipaphrāsa jēhṛā masīha yīśu ca minjō saugī kaidī ai,",null],[1,24,"कने मरकुस कने अरिस्तर्खुस कने देमास कने लूका जेह्ड़ा मेरे सेहकर्मी हन, इन्हां दा तिज्जो नमस्कार ।","kanē marakusa kanē aristarkhusa kanē dēmāsa kanē lūkā jēhṛā mērē sēhakarmī hana, inhāṁ dā tijjō namaskāra .",null],[1,25,"अहां दे प्रभु यीशु मसीह दा अनुग्रह तुहां दी आत्मां पर हुंदा रैंह् । आमीन ।","ahāṁ dē prabhu yīśu masīha dā anugraha tuhāṁ dī ātmāṁ para huṁdā raiṁh . āmīna .",null]],"kfs":[[1,1,"पौलुसा खाते सै जे मसीह यीशु रा कैदी आ, कने भाई तीमुथियुसा खाते अहांरे प्रिय सहकर्मी फिलेमोन,","paulusā khātē sai jē masīha yīśu rā kaidī ā, kanē bhāī tīmuthiyusā khātē ahāṁrē priya sahakarmī philēmōna,",null],[1,2,"कने बैहण अफफिया, कने अहांरे साथी योद्धा अरखिप्पुस कने फिलेमोन रे घरा री कलीसिया रे नौंये :","kanē baihaṇa aphaphiyā, kanē ahāṁrē sāthī yōddhā arakhippusa kanē philēmōna rē gharā rī kalīsiyā rē nauṁyē :",null],[1,3,"आहां रे पिता परमेशर कने प्रभु यीशु मसीह खाते अनुग्रह कने शान्ति तुहां जो मिलदी रौ।","āhāṁ rē pitā paramēśara kanē prabhu yīśu masīha khātē anugraha kanē śānti tuhāṁ jō miladī rau.",null],[1,4,"हऊं सदा परमेशरा रा धन्यवाद करां, कने अपणिया प्राथना च भी तुहां जो याद करां,","haūṁ sadā paramēśarā rā dhanyavāda karāṁ, kanē apaṇiyā prāthanā ca bhī tuhāṁ jō yāda karāṁ,",null],[1,5,"कांभई हऊं तेरे तिस प्रेम कने विस्वासा री चर्चा सुणां, सै जे सब पवित्र लोकां सौगी कने प्रभु यीशु पर ई।","kāṁbhaī haūṁ tērē tisa prēma kanē visvāsā rī carcā suṇāṁ, sai jē saba pavitra lōkāṁ saugī kanē prabhu yīśu para ī.",null],[1,6,"हऊं प्राथना करां भई विस्वासा च तेरा सहभागी हुणा, तेरी सारिया भलाईय रिया पछयाणा च, मसीह पछयाणा च, मसीह खातर प्रभावशाली हो।","haūṁ prāthanā karāṁ bhaī visvāsā ca tērā sahabhāgī huṇā, tērī sāriyā bhalāīya riyā pachayāṇā ca, masīha pachayāṇā ca, masīha khātara prabhāvaśālī hō.",null],[1,7,"कांभई हे भाई, मिन्जो तेरे प्रेमा ते बौहत खुशी कने शान्ति मिलीरी, इस खातर भई तेरे जरिये पवित्र लोकां रे मन हरे भरे हुई गरे।","kāṁbhaī hē bhāī, minjō tērē prēmā tē bauhata khuśī kanē śānti milīrī, isa khātara bhaī tērē jariyē pavitra lōkāṁ rē mana harē bharē huī garē.",null],[1,8,"इस खातर भई मिन्जो मसीह च बड़ी हिम्मत ई भई सै जे गल्लां ठीक ई यां, तिन्हां रा हुक्म तिज्जो देऊं।","isa khātara bhaī minjō masīha ca baṛī himmata ī bhaī sai jē gallāṁ ṭhīka ī yāṁ, tinhāṁ rā hukma tijjō dēūṁ.",null],[1,9,"तां भी मुझ बुढे पौलुसा जो सै जे हुण मसीह यीशु खातर कैदी आ, येढ़ा होर भी खरा जाणेया भई प्यारा ने विनती करूँ।","tāṁ bhī mujha buḍhē paulusā jō sai jē huṇa masīha yīśu khātara kaidī ā, yēṛhā hōra bhī kharā jāṇēyā bhaī pyārā nē vinatī karūm̐.",null],[1,10,"हऊं अपणे बच्चे उनेसिमुसा खातर, सै जे मेरे ते मेरिया कैदा च जम्मी रा, तेरने विनती करां।","haūṁ apaṇē baccē unēsimusā khātara, sai jē mērē tē mēriyā kaidā ca jammī rā, tēranē vinatī karāṁ.",null],[1,11,"सै तां पैहले ई तेरे किछ कम्मा रा नी था, हुण तेरे कने मेरे दुई रे बड़े कम्मा रा।","sai tāṁ paihalē ī tērē kicha kammā rā nī thā, huṇa tērē kanē mērē duī rē baṛē kammā rā.",null],[1,12,"तिस्सो ई मतलब सै जे मेरे दिला रा टुकड़ा आ, मैं तेरे ला भेजी रा।","tissō ī matalaba sai jē mērē dilā rā ṭukaṛā ā, maiṁ tērē lā bhējī rā.",null],[1,13,"तिस्सो हऊं अ‍प्पु लेई रखणा चाह्वां था भई सै तेरिया खाते कैदा च सुसमाचारा रिया वजह तेई, मेरी सेवा करो।","tissō haūṁ appu lēī rakhaṇā cāhvāṁ thā bhaī sai tēriyā khātē kaidā ca susamācārā riyā vajaha tēī, mērī sēvā karō.",null],[1,14,"पर मैं तेरिया इच्छा ते बिना किछ भी करना नीं चाहया, भई तेरी ये कृपा दवाबा ते नीं पर खुशिया ने हो।","para maiṁ tēriyā icchā tē binā kicha bhī karanā nīṁ cāhayā, bhaī tērī yē kr̥pā davābā tē nīṁ para khuśiyā nē hō.",null],[1,15,"कांभई क्या पता सै तेरते थोड़ेया दिनां खातर इस वजह ते लग हुआ भई सदा तेरे नेड़े रहो।","kāṁbhaī kyā patā sai tēratē thōṛēyā dināṁ khātara isa vajaha tē laga huā bhaī sadā tērē nēṛē rahō.",null],[1,16,"पर हुणा ते दासा साई नीं पर दासा ते भी खरा, मतलब भाईये साई रौ, सै जे मेरा तां खाश प्यारा हया ईआ, पर हुण शरीरा च कने प्रभुये च भी, तेरा भी खाशा प्यारा हो।","para huṇā tē dāsā sāī nīṁ para dāsā tē bhī kharā, matalaba bhāīyē sāī rau, sai jē mērā tāṁ khāśa pyārā hayā īā, para huṇa śarīrā ca kanē prabhuyē ca bhī, tērā bhī khāśā pyārā hō.",null],[1,17,"इस खातर जे तु मिन्जो अपणा सहभागी समझां, तां तिस्सो ईयां ग्रहण कर तियां जे मिन्जो करां।","isa khātara jē tu minjō apaṇā sahabhāgī samajhāṁ, tāṁ tissō īyāṁ grahaṇa kara tiyāṁ jē minjō karāṁ.",null],[1,18,"जे तिने तेरा किछ नुक्सान कित्ती रा, या तिस तेरा किछ देणा; तां मेरे नौंवा पर लिखी ले।","jē tinē tērā kicha nuksāna kittī rā, yā tisa tērā kicha dēṇā; tāṁ mērē nauṁvā para likhī lē.",null],[1,19,"हऊं पौलुस अपणे हत्था ते लिखां भई मांह अप्पु भरी देणा; कने इसरे बोलणे री किछ जरुरत नीं भई मेरा कर्ज सै जे तेरे परा सै तु ईआ।","haūṁ paulusa apaṇē hatthā tē likhāṁ bhaī māṁha appu bharī dēṇā; kanē isarē bōlaṇē rī kicha jarurata nīṁ bhaī mērā karja sai jē tērē parā sai tu īā.",null],[1,20,"हे भाई, ये खुशी मिन्जो प्रभुये च तेरिया खाते मिलो। मसीह च मेरे दिला जो हरा-भरा करी दे।","hē bhāī, yē khuśī minjō prabhuyē ca tēriyā khātē milō. masīha ca mērē dilā jō harā-bharā karī dē.",null],[1,21,"हऊं तेरे आज्ञाकारी हुणे रा भरोसा रखी ने तिज्जो लिखां, येढ़ा जाणां भई जो किछ हऊं बोलां, तु तिसते बौहत बधी ने करना।","haūṁ tērē ājñākārī huṇē rā bharōsā rakhī nē tijjō likhāṁ, yēṛhā jāṇāṁ bhaī jō kicha haūṁ bōlāṁ, tu tisatē bauhata badhī nē karanā.",null],[1,22,"कने ये भी भई मेरे खातर ठेहरने री जगहा तैयार रख। मिन्जो आशा ई भई तुहां रिया प्राथनावां जे हऊं तिज्जो दई दित्या जांगा।","kanē yē bhī bhaī mērē khātara ṭhēharanē rī jagahā taiyāra rakha. minjō āśā ī bhaī tuhāṁ riyā prāthanāvāṁ jē haūṁ tijjō daī dityā jāṁgā.",null],[1,23,"इपफ्रास, सै जे मसीह यीशुये च मेरे सौगी कैदी आ,","ipaphrāsa, sai jē masīha yīśuyē ca mērē saugī kaidī ā,",null],[1,24,"कने मरकुस कने अरिस्तर्खुस कने देमास कने लूका सै जे मेरे सहकर्मी ये, इन्हां रा तिज्जो नमस्कार।","kanē marakusa kanē aristarkhusa kanē dēmāsa kanē lūkā sai jē mērē sahakarmī yē, inhāṁ rā tijjō namaskāra.",null],[1,25,"अहांरे प्रभु मसीह रा अनुग्रह तुहांरिया आत्मा पर हुन्दा रौ। आमीन।","ahāṁrē prabhu masīha rā anugraha tuhāṁriyā ātmā para hundā rau. āmīna.",null]],"mjl":[[1,1,"पौलुसा री तरफा ले जो यीसू मसीहा रा बंदी आ, होर भाई तीमुथियुसा री वखा ले आस्सा रा प्यारा दोस्त होर साउगी सेउआ करणे वाळा फिलेमोन l","paulusā rī taraphā lē jō yīsū masīhā rā baṁdī ā, hōra bhāī tīmuthiyusā rī vakhā lē āssā rā pyārā dōsta hōra sāugī sēuā karaṇē vāḷā philēmōna l",null],[1,2,"होर आस्सा री बैहण अफ़िया, आस्सा साउगी स्पाही रा काम करणे वाळे अर्ख़िप्पुस होर तेस झुण्डा जो जेहड़ा मण्डली रे रूपा मन्झ तुस्से रे घरा कठा हुहां आ l","hōra āssā rī baihaṇa afiyā, āssā sāugī spāhī rā kāma karaṇē vāḷē ark͟hippusa hōra tēsa jhuṇḍā jō jēhaṛā maṇḍalī rē rūpā manjha tussē rē gharā kaṭhā huhāṁ ā l",null],[1,3,"आस्सा रे पिता परमेसर होर प्रभु यीसू मसीह री तरफा ले दया होर सांति तुस्सा जो मिल्दी रैहे l","āssā rē pitā paramēsara hōra prabhu yīsū masīha rī taraphā lē dayā hōra sāṁti tussā jō mildī raihē l",null],[1,4,"आपणी प्रार्थना मन्झ तुस्सा जो याद करी किन्हें हांऊ परमेसरा रा धन्याबाद करहा l","āpaṇī prārthanā manjha tussā jō yāda karī kinhēṁ hāṁū paramēsarā rā dhanyābāda karahā l",null],[1,5,"तेरे तेस प्यार होर विस्वासा री चर्चा सुणहांं ऐं, जो सभ पवित्र लोका साउगी होर प्रभु यीसू पर ई l","tērē tēsa pyāra hōra visvāsā rī carcā suṇahāṁṁ aiṁ, jō sabha pavitra lōkā sāugī hōra prabhu yīsū para ī l",null],[1,6,"मेरी अरज ये ई कि तुस्सा रे विस्वासा ले जम्मी री उदार सैहभागिता किन्हें लोका रा अगुवाई करे l जेस ले तिन्हा जो तिन्हा सभी खरी गल्ला री समझ हुई जाए जो मसीहा रे मकस्दा जो अगे बढ़ाणे मन्झ जेहड़ी आस्सा मन्झ हुएया करहा ई l","mērī araja yē ī ki tussā rē visvāsā lē jammī rī udāra saihabhāgitā kinhēṁ lōkā rā aguvāī karē l jēsa lē tinhā jō tinhā sabhī kharī gallā rī samajha huī jāē jō masīhā rē makasdā jō agē baṛhāṇē manjha jēhaṛī āssā manjha huēyā karahā ī l",null],[1,7,"क्यूंकि हे भाई, मुंजो तेरे प्यारा ले बौहत खुसी होर तसल्ली मिली गई l इधी कठे, कि तेरे जरिये पवित्र लोका रे मन हरे भरे हुई गये l","kyūṁki hē bhāī, muṁjō tērē pyārā lē bauhata khusī hōra tasallī milī gaī l idhī kaṭhē, ki tērē jariyē pavitra lōkā rē mana harē bharē huī gayē l",null],[1,8,"एस वजहा ले हांऊ मसीह मन्झ इतनी हिम्मत मैहसूस करहा, कि जो गल ठीक ई, तेता रा हुकम हांऊ तुजो देई सकूं l","ēsa vajahā lē hāṁū masīha manjha itanī himmata maihasūsa karahā, ki jō gala ṭhīka ī, tētā rā hukama hāṁū tujō dēī sakūṁ l",null],[1,9,"तेबे भी मुंजो बुढे पौलुसा जो, जो एबे मसीह यीसू रे कठे बंदी आ, ये होर भी खरा लग्या कि हांऊ प्यारा किन्हें अरज करूं l","tēbē bhī muṁjō buḍhē paulusā jō, jō ēbē masīha yīsū rē kaṭhē baṁdī ā, yē hōra bhī kharā lagyā ki hāṁū pyārā kinhēṁ araja karūṁ l",null],[1,10,"हांऊ आपणे म्हठे उनेसिमुसा री स्पार्स करहा जो जेहला मन्झ मेरे ले जम्मेया तुध ले अरज करहा l","hāṁū āpaṇē mhaṭhē unēsimusā rī spārsa karahā jō jēhalā manjha mērē lē jammēyā tudha lē araja karahā l",null],[1,11,"पैहले ता से तेरे कोई कामा रा नी था, पर एभे से तेरे कठे होर मेरे कठे बड़े कामा रा आ ।","paihalē tā sē tērē kōī kāmā rā nī thā, para ēbhē sē tērē kaṭhē hōra mērē kaṭhē baṛē kāmā rā ā .",null],[1,12,"तेस जो मतलब जो मेरे दिला रा टुकड़ा आ, तेस जो हांऊ तेरे वाले वाप्स भेज्या करहा l","tēsa jō matalaba jō mērē dilā rā ṭukaṛā ā, tēsa jō hāṁū tērē vālē vāpsa bhējyā karahā l",null],[1,13,"असली मन्झ हांऊ तेस जो आपणे नेडे रखणा चाहां था ताकि एस जेहला मन्झ से तेरी तरफा ले मेरी सेऊआ करे l","asalī manjha hāṁū tēsa jō āpaṇē nēḍē rakhaṇā cāhāṁ thā tāki ēsa jēhalā manjha sē tērī taraphā lē mērī sēūā karē l",null],[1,14,"पर मैं तेरी मरजी बगैर कुछ करणा नी चाहेया ताकि तेरी ये किरपा दबाबा ले नी पर खुसी री वजहा ले हो l","para maiṁ tērī marajī bagaira kucha karaṇā nī cāhēyā tāki tērī yē kirapā dabābā lē nī para khusī rī vajahā lē hō l",null],[1,15,"क्यूंकि क्या जाणे से तेरे ले कुछ ध्याड़े इधी कठे तुध ले लग हुएया ताकि से हमेसा रे कठे तेरे वाले रही सके l","kyūṁki kyā jāṇē sē tērē lē kucha dhyāṛē idhī kaṭhē tudha lē laga huēyā tāki sē hamēsā rē kaṭhē tērē vālē rahī sakē l",null],[1,16,"पर एभे से दासा आ साहीं नी आ, बल्कि दासा ले भी खरा आ, मतलब भाई साहीं रहे, जो मेरे कठे ता खास प्यारा आ, पर एभे सरीरा मन्झ होर ख़ास करी किन्हें प्रभु मन्झ तेरा भी प्यारा आ l","para ēbhē sē dāsā ā sāhīṁ nī ā, balki dāsā lē bhī kharā ā, matalaba bhāī sāhīṁ rahē, jō mērē kaṭhē tā khāsa pyārā ā, para ēbhē sarīrā manjha hōra k͟hāsa karī kinhēṁ prabhu manjha tērā bhī pyārā ā l",null],[1,17,"अगर तू मुंजो आपणा साथी समझ्हा ता तेस जोमेरे साहीं मनी ले l","agara tū muṁjō āpaṇā sāthī samajhhā tā tēsa jōmērē sāhīṁ manī lē l",null],[1,18,"होर अगर से तेरा कुछ नुकसान करी बैठिरा या से तेरा लेणदार हुई गईरा, ता से सभ कुछ मेरे नांऊआंं पर लिखी दे l","hōra agara sē tērā kucha nukasāna karī baiṭhirā yā sē tērā lēṇadāra huī gaīrā, tā sē sabha kucha mērē nāṁūāṁṁ para likhī dē l",null],[1,19,"हांऊ पौलुस आपणे ई हाथ ले एस गल्ला जो लिख्हा, कि मां तेसरा कर्जा आपु ऐ भरी देणा; होर ये बोलण री जरुरत नी हाई कि तू आपु मेरा जिन्दगी भरा रे कठे लेणदार आ l","hāṁū paulusa āpaṇē ī hātha lē ēsa gallā jō likhhā, ki māṁ tēsarā karjā āpu ai bharī dēṇā; hōra yē bōlaṇa rī jarurata nī hāī ki tū āpu mērā jindagī bharā rē kaṭhē lēṇadāra ā l",null],[1,20,"हे भाई ये खुसी मुंजो प्रभु मन्झ तेरी तरफ़ा ले मिली जाए: मसीह मन्झ मेरी जिन्दगी जो ताजा करी दे l","hē bhāī yē khusī muṁjō prabhu manjha tērī tarafā lē milī jāē: masīha manjha mērī jindagī jō tājā karī dē l",null],[1,21,"हांऊ तेरी मानदारी पर तबार करी किन्हें, तुजो ये लिख्या करहा होर ये जाणहांं , कि जो कुछ हांऊ बोल्हा, तुध तेता ले बढ़ी किन्हें करणा l","hāṁū tērī mānadārī para tabāra karī kinhēṁ, tujō yē likhyā karahā hōra yē jāṇahāṁṁ , ki jō kucha hāṁū bōlhā, tudha tētā lē baṛhī kinhēṁ karaṇā l",null],[1,22,"होर तेरे ले एक अरज करहा कि, मेरे कठे एक कमरा त्यार करी के रक्खेया, क्यूंकि मुंजो आस ई, कि तुस्सा री प्रार्थना रे जबाबा मन्झ हांऊ तुस्सा जो वाप्स मिली जाणा l","hōra tērē lē ēka araja karahā ki, mērē kaṭhē ēka kamarā tyāra karī kē rakkhēyā, kyūṁki muṁjō āsa ī, ki tussā rī prārthanā rē jabābā manjha hāṁū tussā jō vāpsa milī jāṇā l",null],[1,23,"इपफ़्रास जेहड़ा मसीह यीसू मन्झ मेरे साउगी कैदी आ तुस्सा जो नमस्ते बोल्हा l","ipafrāsa jēhaṛā masīha yīsū manjha mērē sāugī kaidī ā tussā jō namastē bōlhā l",null],[1,24,"होर मरकुस, अरिस्तर्खुस, देमास होर लूका जो मेरे साउगी काम करहा ऐ इन्हा रा तुजो नमस्कार l","hōra marakusa, aristarkhusa, dēmāsa hōra lūkā jō mērē sāugī kāma karahā ai inhā rā tujō namaskāra l",null],[1,25,"आस्सा रे प्रभु यीसू मसीहा री दया तुस्सा री आत्मा पर हुन्दी रहे l","āssā rē prabhu yīsū masīhā rī dayā tussā rī ātmā para hundī rahē l",null]],"bfz":[[1,1,"ये चिट्ठी मां पौलुसो री तरफा ते ए। आँऊ कैदा रे ए कऊँकि आँऊ यीशु मसीह रे सुसमाचारो रा प्रचार करूँआ। मेरा और आसा रे साथी विश्वासी तीमुथियुसो री तरफा ते ताखे नमस्कार। ओ फिलेमोन मां साथे काम करने वाल़े मेरे प्यारे दोस्त आँऊ ये चिट्ठी ताखे लिखणे लगी रा।","yē ciṭṭhī māṁ paulusō rī taraphā tē ē. ām̐ū kaidā rē ē kaūm̐ki ām̐ū yīśu masīha rē susamācārō rā pracāra karūm̐ā. mērā aura āsā rē sāthī viśvāsī tīmuthiyusō rī taraphā tē tākhē namaskāra. ō philēmōna māṁ sāthē kāma karanē vāl̈ē mērē pyārē dōsta ām̐ū yē ciṭṭhī tākhē likhaṇē lagī rā.",null],[1,2,"आँऊ ये चिट्ठी आसा री विश्वासी बईण अफफिया और पाई अरखिप्पुस जो प्रभुए री सेवा एक योद्धा जेड़ी करोआ और तेसा मण्डल़िया के बी जो तुसा रे कअरे कट्ठी ओई लिखणे लगी रा।","ām̐ū yē ciṭṭhī āsā rī viśvāsī baīṇa aphaphiyā aura pāī arakhippusa jō prabhuē rī sēvā ēka yōddhā jēṛī karōā aura tēsā maṇḍal̈iyā kē bī jō tusā rē kaarē kaṭṭhī ōī likhaṇē lagī rā.",null],[1,3,"आँऊ प्रार्थना करूँआ कि म्हारे पिता परमेशर और प्रभु यीशु मसीह री तरफा ते ताखे कृपा और शान्ति मिलदी रओ।","ām̐ū prārthanā karūm̐ā ki mhārē pitā paramēśara aura prabhu yīśu masīha rī taraphā tē tākhē kr̥pā aura śānti miladī raō.",null],[1,4,"जेबे कदी बी आऊँ ताखे प्रार्थना करूँआ तो सदा ताखे परमेशरो रा धन्यवाद करूँआ।","jēbē kadī bī āūm̐ tākhē prārthanā karūm̐ā tō sadā tākhē paramēśarō rā dhanyavāda karūm̐ā.",null],[1,5,"कऊँकि आँऊ प्रभु यीशुए पाँदे तेरे विश्वास और परमेशरो रे लोका खे तेरे प्यारो रे बारे रे सुणने लगी रा।","kaūm̐ki ām̐ū prabhu yīśuē pām̐dē tērē viśvāsa aura paramēśarō rē lōkā khē tērē pyārō rē bārē rē suṇanē lagī rā.",null],[1,6,"आऊँ प्रार्थना करूँआ कि तेरी से साजेदारी जो विश्वासिया साथे ए और बी बड़दी जाओ। ताकि आसे सब ये जाणी सकिए कि आसे लोक मसीह पीछे चली की कितणे आशीषित ए।","āūm̐ prārthanā karūm̐ā ki tērī sē sājēdārī jō viśvāsiyā sāthē ē aura bī baṛadī jāō. tāki āsē saba yē jāṇī sakiē ki āsē lōka masīha pīchē calī kī kitaṇē āśīṣita ē.",null],[1,7,"ओ दोस्त, माखे तेरे प्यारो ते बऊत खुशी और शान्ति मिली, कऊँकि तेरे जरिए परमेशरो रे लोका रे मन खुश ऊईगे।","ō dōsta, mākhē tērē pyārō tē baūta khuśī aura śānti milī, kaūm̐ki tērē jariē paramēśarō rē lōkā rē mana khuśa ūīgē.",null],[1,8,"ओ फिलेमोन, आँऊ तुसा ते एक निवेदन करूँआ हालाँकि आँऊ मसीह रा प्रेरित ऊणे रे नाते तुसा खे जो करना चाईयो तिजी खे अक्को साथे एसा गल्ला खे करने री आज्ञा देई सकूँआ","ō philēmōna, ām̐ū tusā tē ēka nivēdana karūm̐ā hālām̐ki ām̐ū masīha rā prērita ūṇē rē nātē tusā khē jō karanā cāīyō tijī khē akkō sāthē ēsā gallā khē karanē rī ājñā dēī sakūm̐ā",null],[1,9,"तेबे बी मां स्याणे पौलुसो खे, जो एबे यीशु मसीह रा सुसमाचार सुनाणे री बजअ ते जेला रे कैद ए, ये ओर बी खरा लगेया कि प्यारो साथे तुसा ते बिनती करुँ।","tēbē bī māṁ syāṇē paulusō khē, jō ēbē yīśu masīha rā susamācāra sunāṇē rī bajaa tē jēlā rē kaida ē, yē ōra bī kharā lagēyā ki pyārō sāthē tusā tē binatī karum̐.",null],[1,10,"आऊँ उनेसिमुसो खे विनती करूँआ जो मेरे पाऊए जेड़ा ए। से मसीह रे मेरा पाऊ बणीगा जेबे आँऊ जेला रे था।","āūm̐ unēsimusō khē vinatī karūm̐ā jō mērē pāūē jēṛā ē. sē masīha rē mērā pāū baṇīgā jēbē ām̐ū jēlā rē thā.",null],[1,11,"से पईले तो तेरे किजी कामो रा नि था, पर एबे तेरे और मेरे दूँईं रे बड़े कामो राए।","sē paīlē tō tērē kijī kāmō rā ni thā, para ēbē tērē aura mērē dūm̐īṁ rē baṛē kāmō rāē.",null],[1,12,"तेसखे ई, मतलब जो मेरे काल़जे रा टुकड़ा ए, मैं से तांगे वापस पेजी ता रा।","tēsakhē ī, matalaba jō mērē kāl̈ajē rā ṭukaṛā ē, maiṁ sē tāṁgē vāpasa pējī tā rā.",null],[1,13,"तेसखे आऊँ आपू गे ई राखणा चाऊँ था कि तेरी तरफा ते एसा कैदा रे जो सुसमाचारो री बजअ ते ए, मेरी सेवा करो।","tēsakhē āūm̐ āpū gē ī rākhaṇā cāūm̐ thā ki tērī taraphā tē ēsā kaidā rē jō susamācārō rī bajaa tē ē, mērī sēvā karō.",null],[1,14,"पर मैं तेरी इच्छा ते बिना कुछ बी करना नि चाया, ताकि तेरी ये कृपा दबाओ रे नि पर खुशिया साथे ओ।","para maiṁ tērī icchā tē binā kucha bī karanā ni cāyā, tāki tērī yē kr̥pā dabāō rē ni para khuśiyā sāthē ō.",null],[1,15,"क्या पता उनेसिमुस इजी बजअ ते कुछ दिनो खे नठी गा ताकि से मसीह पाँदे विश्वास करी सको और से ताखे सदा खे मिली जाओ।","kyā patā unēsimusa ijī bajaa tē kucha dinō khē naṭhī gā tāki sē masīha pām̐dē viśvāsa karī sakō aura sē tākhē sadā khē milī jāō.",null],[1,16,"पर आजो ते दासा जेड़ा नि, बल्कि दासो ते बी खरा, मतलब-पाईए जेड़ा रओ, जो मेरा तो खास प्यारा आए ई, पर एबे मांणूआ रे रूपो रे और प्रभुए रे बी, से तेरा खास प्यारा ओ।","para ājō tē dāsā jēṛā ni, balki dāsō tē bī kharā, matalaba-pāīē jēṛā raō, jō mērā tō khāsa pyārā āē ī, para ēbē māṁṇūā rē rūpō rē aura prabhuē rē bī, sē tērā khāsa pyārā ō.",null],[1,17,"जे तूँ माखे आपणा साथी समजेया, तो तेसखे ईंयां ग्रहण करी लओ, जेड़ा माखे।","jē tūm̐ mākhē āpaṇā sāthī samajēyā, tō tēsakhē īṁyāṁ grahaṇa karī laō, jēṛā mākhē.",null],[1,18,"जे तिने तेरा कुछ नुकशाण करी राखेया या से तेरा कर्जदार ए, तो मेरे नाओं दे लिखी लो।","jē tinē tērā kucha nukaśāṇa karī rākhēyā yā sē tērā karjadāra ē, tō mērē nāōṁ dē likhī lō.",null],[1,19,"आऊँ पौलुस आपणे आथो साथे लिखूँआ कि मां आपू ई तेसरा कर्जा परी देणा। इजी री बोलणे री जरूरत निए कि तेरी सारी जिन्दगी मेरी कर्जदार ए।","āūm̐ paulusa āpaṇē āthō sāthē likhūm̐ā ki māṁ āpū ī tēsarā karjā parī dēṇā. ijī rī bōlaṇē rī jarūrata niē ki tērī sārī jindagī mērī karjadāra ē.",null],[1,20,"ओ मेरे प्यारे दोस्त, ये खुशी माखे प्रभुए रे तेरी तरफा ते मिलो। मसीह रे मेरे जिऊओ खे अरा-फरा करी दे।","ō mērē pyārē dōsta, yē khuśī mākhē prabhuē rē tērī taraphā tē milō. masīha rē mērē jiūō khē arā-pharā karī dē.",null],[1,21,"आऊँ तेरे आज्ञाकारी ऊणे रा विश्वास करी की ताखे लिखूँआ और ये जाणूंआ कि जो कुछ आऊँ बोलूँआ, तां तिजी ते बी केथी ओर बड़ी की करना।","āūm̐ tērē ājñākārī ūṇē rā viśvāsa karī kī tākhē likhūm̐ā aura yē jāṇūṁā ki jō kucha āūm̐ bōlūm̐ā, tāṁ tijī tē bī kēthī ōra baṛī kī karanā.",null],[1,22,"और ये बी कि माखे रणे खे जगा त्यार राख, माखे उम्मीद ए कि तुसा री प्रार्थना रे जरिए परमेशरो तुसा री प्रार्थना रा जवाब देणा और आऊँ तुसा गे फेर आयी जाणा।","aura yē bī ki mākhē raṇē khē jagā tyāra rākha, mākhē ummīda ē ki tusā rī prārthanā rē jariē paramēśarō tusā rī prārthanā rā javāba dēṇā aura āūm̐ tusā gē phēra āyī jāṇā.",null],[1,23,"इपफ्रास जो मां साथे यीशु मसीह रा सुसमाचार सुनाणे री बजअ ते कैदी ए से ताखे नमस्कार बोलोआ।","ipaphrāsa jō māṁ sāthē yīśu masīha rā susamācāra sunāṇē rī bajaa tē kaidī ē sē tākhē namaskāra bōlōā.",null],[1,24,"और मरकुस, अरिस्तर्खुस, देमास और लूका जो मां साथे प्रभुए रा काम करने वाल़े ए, इना री ताखे नमस्कार।","aura marakusa, aristarkhusa, dēmāsa aura lūkā jō māṁ sāthē prabhuē rā kāma karanē vāl̈ē ē, inā rī tākhē namaskāra.",null],[1,25,"आँऊ प्रार्थना करूँआ कि म्हारे प्रभु यीशु मसीह री कृपा तुसा री आत्मा पाँदे ऊँदी रओ। आमीन्।","ām̐ū prārthanā karūm̐ā ki mhārē prabhu yīśu masīha rī kr̥pā tusā rī ātmā pām̐dē ūm̐dī raō. āmīn.",null]],"bhd":[[1,1,"अवं पौलुस ई चिट्ठी लिखने लोरोईं। अवं कैदे मां आईं किजोकि अवं यीशु मसीहेरे बारे मां प्रचार केरताईं। हे फिलेमोन तीं इश्शे ढ्ला तीमुथियुस ते मेरे तरफां नमस्कार। तू इश्शो ट्लारो दोस्तस आस ते ज़ेन्च़रे अस मसीहेरे लेइ कम केरतम तेन्च़रे तू भी केरतस।","avaṁ paulusa ī ciṭṭhī likhanē lōrōīṁ. avaṁ kaidē māṁ āīṁ kijōki avaṁ yīśu masīhērē bārē māṁ pracāra kēratāīṁ. hē philēmōna tīṁ iśśē ḍhlā tīmuthiyusa tē mērē taraphāṁ namaskāra. tū iśśō ṭlārō dōstasa āsa tē zēnc̈arē asa masīhērē lēi kama kēratama tēnc̈arē tū bhī kēratasa.",null],[1,2,"अवं इश्शी विश्वासी बेइन अफफिया ते इश्शे सैथी अरखिप्पुस ज़ै सिपेहेरे ज़ेरो प्रभुएरी सेवा केरते, ते तैन कलीसियारे लोक ज़ैना तेरे घरे मां अकोट्ठे भोतन, तैन भी लिखने लोरोईं,","avaṁ iśśī viśvāsī bēina aphaphiyā tē iśśē saithī arakhippusa zai sipēhērē zērō prabhuērī sēvā kēratē, tē taina kalīsiyārē lōka zainā tērē gharē māṁ akōṭṭhē bhōtana, taina bhī likhanē lōrōīṁ,",null],[1,3,"अवं प्रार्थना केरताईं, इश्शे बाजी परमेशर ते प्रभु यीशु मसीह तुसन पुड़ अनुग्रह केरे ते तुसन शान्ति दे।","avaṁ prārthanā kēratāīṁ, iśśē bājī paramēśara tē prabhu yīśu masīha tusana puṛa anugraha kērē tē tusana śānti dē.",null],[1,4,"अवं ज़ैखन भी तेरे लेइ प्रार्थना केरताईं, तेरे लेइ अवं परमेशरेरू शुक्र केरताईं।","avaṁ zaikhana bhī tērē lēi prārthanā kēratāīṁ, tērē lēi avaṁ paramēśarērū śukra kēratāīṁ.",null],[1,5,"किजोकि मीं प्रभु यीशु मां तेरे विश्वासेरे बारे मां ते परमेशरेरे लोकां केरे लेइ तेरे प्यारे बारे मां शुनू।","kijōki mīṁ prabhu yīśu māṁ tērē viśvāsērē bārē māṁ tē paramēśarērē lōkāṁ kērē lēi tērē pyārē bārē māṁ śunū.",null],[1,6,"अवं प्रार्थना केरताईं तेरी संगती ज़ै विश्वासी लोकन सेइं साथीए, तुश्शे तैन रोड़ि चीज़ां केरे ज़ान्नेरे ज़िरिये ज़ैना परमेशरे दित्तोरिन बद्धती गाए। इन मसीहेरे महिमारे लेइ भोतू राए।","avaṁ prārthanā kēratāīṁ tērī saṁgatī zai viśvāsī lōkana sēiṁ sāthīē, tuśśē taina rōṛi cīzāṁ kērē zānnērē ziriyē zainā paramēśarē dittōrina baddhatī gāē. ina masīhērē mahimārē lēi bhōtū rāē.",null],[1,7,"किजोकि हे ढ्ला, अवं तेरे प्यारे सेइं ज़ै तू मीं केरतस बड़ो खुश आई, ते मीं बड़ो होसलो भोव, एल्हेरेलेइ कि तेरे प्यारेरे ज़िरिये होरि परमेशरेरे लोकन भी होसलो मैल्लो।","kijōki hē ḍhlā, avaṁ tērē pyārē sēiṁ zai tū mīṁ kēratasa baṛō khuśa āī, tē mīṁ baṛō hōsalō bhōva, ēlhērēlēi ki tērē pyārērē ziriyē hōri paramēśarērē lōkana bhī hōsalō maillō.",null],[1,8,"अवं तीं किछ केरनेरे लेइ पुछ़ताई ज़ैन तीं कियोरू लोड़े। अवं मसीहेरो दित्तोरे अधिकारे इस्तेमाल केरतां इन केरनेरे लेइ हुक्म देइ बटतो थियो, पन अवं न केरेलो। इसेरे बदले मां, अवं बल्हे च़ारे ज़ोताईं कि तू इन केर, किजोकि अस एक्की होरि सेइं ते परमेशरेरे लोकन सेइं प्यार केरतम। अवं पौलुस हुनी सियाने मैनेरे रूपे मां तीं पुछ़तईं, अवं लोकेईं कैदे मां बंद कियोरोईं किजोकि अवं यीशु मसीहेरी सेवा केरताईं।","avaṁ tīṁ kicha kēranērē lēi pucḧatāī zaina tīṁ kiyōrū lōṛē. avaṁ masīhērō dittōrē adhikārē istēmāla kēratāṁ ina kēranērē lēi hukma dēi baṭatō thiyō, pana avaṁ na kērēlō. isērē badalē māṁ, avaṁ balhē c̈ārē zōtāīṁ ki tū ina kēra, kijōki asa ēkkī hōri sēiṁ tē paramēśarērē lōkana sēiṁ pyāra kēratama. avaṁ paulusa hunī siyānē mainērē rūpē māṁ tīṁ pucḧataīṁ, avaṁ lōkēīṁ kaidē māṁ baṁda kiyōrōīṁ kijōki avaṁ yīśu masīhērī sēvā kēratāīṁ.",9],[1,10,"अवं उनेसिमुसेरे लेइ मिनत केरताईं ज़ैन मेरे लेइ मट्ठेरू ज़ेरूए। तैन मसीह मां मेरू मट्ठू इड़ी कैदखाने मां बनू।","avaṁ unēsimusērē lēi minata kēratāīṁ zaina mērē lēi maṭṭhērū zērūē. taina masīha māṁ mērū maṭṭhū iṛī kaidakhānē māṁ banū.",null],[1,11,"तै बीतोरे वक्ते मां तेरे लेइ केन्ची कम्मेरो न थियो, पन हुनी तेरे त कने मेरे दुइयां केरे बड़े कम्मेरोए।","tai bītōrē vaktē māṁ tērē lēi kēncī kammērō na thiyō, pana hunī tērē ta kanē mērē duiyāṁ kērē baṛē kammērōē.",null],[1,12,"अवं उनेसिमुसे तीं कां वापस भेज़ने लोरोईं, तैस सेइं अवं पूरे दिले सेइं प्यार केरताईं।","avaṁ unēsimusē tīṁ kāṁ vāpasa bhēzanē lōrōīṁ, taisa sēiṁ avaṁ pūrē dilē sēiṁ pyāra kēratāīṁ.",null],[1,13,"अवं ज़ांतगर खुशखबरी प्रचार केरनेरे वजाई कैदखाने मां आईं तांतगर तैस अपनि मद्दत केरनेरे लेइ इड़ी एप्पू सेइं साथी रखनो चातो थियो। ताके तै तेरे ठैरी मेरी मद्दत केरे, किजोकि अवं ज़ानताईं तू मेरी मद्दत केरनि चातस।","avaṁ zāṁtagara khuśakhabarī pracāra kēranērē vajāī kaidakhānē māṁ āīṁ tāṁtagara taisa apani maddata kēranērē lēi iṛī ēppū sēiṁ sāthī rakhanō cātō thiyō. tākē tai tērē ṭhairī mērī maddata kērē, kijōki avaṁ zānatāīṁ tū mērī maddata kērani cātasa.",null],[1,14,"पन मीं तेरी मेर्ज़ी बगैर किछ भी केरनू न चाव, अवं चाताईं तू ई मेरी मद्दत केर, किजोकि तू इन केरनेरे लेइ खुश आस ते एल्हेरेलेइ नईं कि अवं इन केरनेरे लेइ दबाव बनाने लोरोईं।","pana mīṁ tērī mērzī bagaira kicha bhī kēranū na cāva, avaṁ cātāīṁ tū ī mērī maddata kēra, kijōki tū ina kēranērē lēi khuśa āsa tē ēlhērēlēi naīṁ ki avaṁ ina kēranērē lēi dabāva banānē lōrōīṁ.",null],[1,15,"शैइद परमेशरे उनेसिमुस एल्हेरेलेइ तीं करां नश्शने दित्तो, ताके तै मसीह पुड़ विश्वास केरे, ते तैसेरो नितीजो ई भोए कि तै हमेशा तीं सेइं साथी राए।","śaiida paramēśarē unēsimusa ēlhērēlēi tīṁ karāṁ naśśanē dittō, tākē tai masīha puṛa viśvāsa kērē, tē taisērō nitījō ī bhōē ki tai hamēśā tīṁ sēiṁ sāthī rāē.",null],[1,16,"पन हुनी तै तेरो गुलाम नईं, बल्के गुलामे करां भी बेद्धतां आए। तै हुनी तेरो ट्लारो विश्वासी ढ्ला आए। अवं तैस सेइं बड़ो प्यार केरताईं, पन तीं तैस अपने गुलामेरे रूपे मां होरो भी प्यार कियोरो लोड़े किजोकि तै मसीह मां अक ढ्लाए।","pana hunī tai tērō gulāma naīṁ, balkē gulāmē karāṁ bhī bēddhatāṁ āē. tai hunī tērō ṭlārō viśvāsī ḍhlā āē. avaṁ taisa sēiṁ baṛō pyāra kēratāīṁ, pana tīṁ taisa apanē gulāmērē rūpē māṁ hōrō bhī pyāra kiyōrō lōṛē kijōki tai masīha māṁ aka ḍhlāē.",null],[1,17,"अगर तू मीं शामिल समझ़तस, त ज़ैखन उनेसिमुस वापस तीं कां एज्जे त तैस एन्च़रे कबूल केर ज़ेन्च़रे मीं।","agara tū mīṁ śāmila samajḧatasa, ta zaikhana unēsimusa vāpasa tīṁ kāṁ ējjē ta taisa ēnc̈arē kabūla kēra zēnc̈arē mīṁ.",null],[1,18,"ते अगर तैने किछ तेरो नुकसान कियोरोए, या तेरे किछ पेइंसां केरो कर्ज़ो भोए त अवं तैसेरे बदले देइलो।","tē agara tainē kicha tērō nukasāna kiyōrōē, yā tērē kicha pēiṁsāṁ kērō karzō bhōē ta avaṁ taisērē badalē dēilō.",null],[1,19,"अवं पौलुस अपने हथ्थन सेइं लिखताईं, कि अवं तीं एप्पू वापस देइलो, तू इन पेइलू ज़ानतस, अगर मीं तेरी मद्दत न भोथी कियोरी त तीं अपने आपे सेइं न भोथू मैलोरू, मेरो कर्ज़ो ज़ै तीं पुड़े तै तेरी अपनि ज़िन्दगी आए।","avaṁ paulusa apanē haththana sēiṁ likhatāīṁ, ki avaṁ tīṁ ēppū vāpasa dēilō, tū ina pēilū zānatasa, agara mīṁ tērī maddata na bhōthī kiyōrī ta tīṁ apanē āpē sēiṁ na bhōthū mailōrū, mērō karzō zai tīṁ puṛē tai tērī apani zindagī āē.",null],[1,20,"हे मेरे ट्लारे दोस्त, साथी विश्वासी भोनेरे वजाई सेइं इन मेरे लेइ केर ते मसीह मां मीं खुश केर।","hē mērē ṭlārē dōsta, sāthī viśvāsī bhōnērē vajāī sēiṁ ina mērē lēi kēra tē masīha māṁ mīṁ khuśa kēra.",null],[1,21,"मीं ई चिट्ठी लिखोरीए, किजोकि मीं याकीन कि ज़ैन केरनेरे लेइ ज़ोरू तैन तू केरेलो। हकीकति मां अवं ज़ानताईं तू तैस करां भी बड़ू जादे केरेलो, ज़ैन केरनेरे लेइ मीं ज़ोरूए।","mīṁ ī ciṭṭhī likhōrīē, kijōki mīṁ yākīna ki zaina kēranērē lēi zōrū taina tū kērēlō. hakīkati māṁ avaṁ zānatāīṁ tū taisa karāṁ bhī baṛū jādē kērēlō, zaina kēranērē lēi mīṁ zōrūē.",null],[1,22,"ते अक होरि गल, तू अपने घरे मां मेरे लेइ अक कमरो तियार केर। किजोकि मीं उमीदे परमेशर तुश्शे प्रार्थनां केरो जुवाब देलो ते तीं कां फिरी एजने देलो।","tē aka hōri gala, tū apanē gharē māṁ mērē lēi aka kamarō tiyāra kēra. kijōki mīṁ umīdē paramēśara tuśśē prārthanāṁ kērō juvāba dēlō tē tīṁ kāṁ phirī ējanē dēlō.",null],[1,23,"इपफ्रास, ज़ै यीशु मसीहेरी खुशखबरी प्रचार केरनेरे वजाई सेइं मीं साथी कैदीए तै तीं नमस्कार ज़ोते।","ipaphrāsa, zai yīśu masīhērī khuśakhabarī pracāra kēranērē vajāī sēiṁ mīṁ sāthī kaidīē tai tīṁ namaskāra zōtē.",null],[1,24,"ते मरकुस ते अरिस्तर्खुस ते देमास ते लूका ज़ैना प्रभुएरू कम मीं सेइं साथी केरतन तींजो नमस्कार ज़ोतन।","tē marakusa tē aristarkhusa tē dēmāsa tē lūkā zainā prabhuērū kama mīṁ sēiṁ sāthī kēratana tīṁjō namaskāra zōtana.",null],[1,25,"इश्शे प्रभु यीशु मसीहेरो अनुग्रह तुसन पुड़ भोतो राए। आमीन।","iśśē prabhu yīśu masīhērō anugraha tusana puṛa bhōtō rāē. āmīna.",null]],"fin-kr1938":[[1,1,"Paavali, Kristuksen Jeesuksen vanki, ja veli Timoteus rakkaalle Filemonille, työtoverillemme,","Paavali, Kristuksen Jeesuksen vanki, ja veli Timoteus rakkaalle Filemonille, työtoverillemme,",null],[1,2,"ja Appialle, sisarellemme, ja Arkippukselle, taistelutoverillemme, ja sinun kodissasi kokoontuvalle seurakunnalle.","ja Appialle, sisarellemme, ja Arkippukselle, taistelutoverillemme, ja sinun kodissasi kokoontuvalle seurakunnalle.",null],[1,3,"Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!","Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!",null],[1,4,"Minä kiitän Jumalaani aina, muistaessani sinua rukouksissani,","Minä kiitän Jumalaani aina, muistaessani sinua rukouksissani,",null],[1,5,"sillä minä olen kuullut sinun rakkaudestasi ja uskostasi, joka sinulla on Herraan Jeesukseen ja kaikkia pyhiä kohtaan;","sillä minä olen kuullut sinun rakkaudestasi ja uskostasi, joka sinulla on Herraan Jeesukseen ja kaikkia pyhiä kohtaan;",null],[1,6,"ja rukoukseni on, että sinun uskosi, se usko, joka on meille yhteinen, olisi väkevä kaiken hyvän tuntemisessa, mikä meillä Kristuksessa on.","ja rukoukseni on, että sinun uskosi, se usko, joka on meille yhteinen, olisi väkevä kaiken hyvän tuntemisessa, mikä meillä Kristuksessa on.",null],[1,7,"Sillä minä olen saanut paljon iloa ja lohdutusta sinun rakkaudestasi, koska pyhien sydämet ovat virvoittuneet sinun kauttasi, veljeni.","Sillä minä olen saanut paljon iloa ja lohdutusta sinun rakkaudestasi, koska pyhien sydämet ovat virvoittuneet sinun kauttasi, veljeni.",null],[1,8,"Sentähden, vaikka minulla Kristuksessa on paljon rohkeutta käskeä sinua tekemään, mitä tehdä tulee,","Sentähden, vaikka minulla Kristuksessa on paljon rohkeutta käskeä sinua tekemään, mitä tehdä tulee,",null],[1,9,"niin rakkauden tähden minä kuitenkin mieluummin pyydän, ollen tämmöinen kuin olen, minä vanha Paavali, ja nyt myös Kristuksen Jeesuksen vanki-","niin rakkauden tähden minä kuitenkin mieluummin pyydän, ollen tämmöinen kuin olen, minä vanha Paavali, ja nyt myös Kristuksen Jeesuksen vanki-",null],[1,10,"pyydän sinua poikani puolesta, jonka minä kahleissani synnytin, Onesimuksen puolesta,","pyydän sinua poikani puolesta, jonka minä kahleissani synnytin, Onesimuksen puolesta,",null],[1,11,"sinulle ennen hyödyttömän, mutta nyt sekä sinulle että minulle hyödyllisen;","sinulle ennen hyödyttömän, mutta nyt sekä sinulle että minulle hyödyllisen;",null],[1,12,"hänet minä lähetän sinulle takaisin, hänet, se on: oman sydämeni.","hänet minä lähetän sinulle takaisin, hänet, se on: oman sydämeni.",null],[1,13,"Olisin tahtonut pidättää hänet tykönäni, että hän sinun sijassasi olisi palvellut minua, joka olen evankeliumin tähden kahleissa;","Olisin tahtonut pidättää hänet tykönäni, että hän sinun sijassasi olisi palvellut minua, joka olen evankeliumin tähden kahleissa;",null],[1,14,"mutta ilman sinun suostumustasi en tahtonut tehdä mitään, ettei hyvyytesi olisi ikäänkuin pakollinen, vaan vapaaehtoinen.","mutta ilman sinun suostumustasi en tahtonut tehdä mitään, ettei hyvyytesi olisi ikäänkuin pakollinen, vaan vapaaehtoinen.",null],[1,15,"Sillä ehkäpä hän sentähden joutui eroamaan sinusta ajaksi, että saisit hänet takaisin iäksi,","Sillä ehkäpä hän sentähden joutui eroamaan sinusta ajaksi, että saisit hänet takaisin iäksi,",null],[1,16,"ei enää orjana, vaan orjaa enempänä: rakkaana veljenä, ylen rakkaana jo minulle, kuinka paljoa enemmän sitten sinulle, sekä ihmisenä että Herran omana!","ei enää orjana, vaan orjaa enempänä: rakkaana veljenä, ylen rakkaana jo minulle, kuinka paljoa enemmän sitten sinulle, sekä ihmisenä että Herran omana!",null],[1,17,"Jos siis pidät minua toverinasi, niin ota hänet luoksesi niinkuin minut;","Jos siis pidät minua toverinasi, niin ota hänet luoksesi niinkuin minut;",null],[1,18,"mutta jos hän on tehnyt sinulle jotakin vääryyttä tai on sinulle jotakin velkaa, niin pane se minun laskuuni.","mutta jos hän on tehnyt sinulle jotakin vääryyttä tai on sinulle jotakin velkaa, niin pane se minun laskuuni.",null],[1,19,"Minä, Paavali, kirjoitan omalla kädelläni: \"Minä sen maksan\"; saattaisinpa sanoa: pane se omaan laskuusi; sillä sinä olet minulle velkaa oman itsesikin.","Minä, Paavali, kirjoitan omalla kädelläni: \"Minä sen maksan\"; saattaisinpa sanoa: pane se omaan laskuusi; sillä sinä olet minulle velkaa oman itsesikin.",null],[1,20,"Niin, veljeni, jospa saisin sinusta hyötyä Herrassa; virvoita sydäntäni Kristuksessa.","Niin, veljeni, jospa saisin sinusta hyötyä Herrassa; virvoita sydäntäni Kristuksessa.",null],[1,21,"Luottaen kuuliaisuuteesi minä kirjoitan sinulle, ja minä tiedän, että sinä teet enemmänkin, kuin mitä sanon.","Luottaen kuuliaisuuteesi minä kirjoitan sinulle, ja minä tiedän, että sinä teet enemmänkin, kuin mitä sanon.",null],[1,22,"Lisäksi vielä: valmista minulle maja luonasi; toivon näet, että minut rukoustenne kautta lahjoitetaan teille.","Lisäksi vielä: valmista minulle maja luonasi; toivon näet, että minut rukoustenne kautta lahjoitetaan teille.",null],[1,23,"Tervehdyksen lähettävät sinulle Epafras, minun vankitoverini Kristuksessa Jeesuksessa,","Tervehdyksen lähettävät sinulle Epafras, minun vankitoverini Kristuksessa Jeesuksessa,",null],[1,24,"Markus, Aristarkus, Deemas ja Luukas, jotka ovat minun työtovereitani.","Markus, Aristarkus, Deemas ja Luukas, jotka ovat minun työtovereitani.",null],[1,25,"Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa.","Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa.",null]],"engwebp":[[1,1,"Paul, a prisoner of Christ Jesus, and Timothy our brother, to Philemon, our beloved fellow worker,","Paul, a prisoner of Christ Jesus, and Timothy our brother, to Philemon, our beloved fellow worker,",null],[1,2,"to the beloved Apphia, to Archippus our fellow soldier, and to the assembly in your house:","to the beloved Apphia, to Archippus our fellow soldier, and to the assembly in your house:",null],[1,3,"Grace to you and peace from God our Father and the Lord Jesus Christ.","Grace to you and peace from God our Father and the Lord Jesus Christ.",null],[1,4,"I thank my God always, making mention of you in my prayers,","I thank my God always, making mention of you in my prayers,",null],[1,5,"hearing of your love and of the faith which you have toward the Lord Jesus and toward all the saints,","hearing of your love and of the faith which you have toward the Lord Jesus and toward all the saints,",null],[1,6,"that the fellowship of your faith may become effective in the knowledge of every good thing which is in us in Christ Jesus.","that the fellowship of your faith may become effective in the knowledge of every good thing which is in us in Christ Jesus.",null],[1,7,"For we have much joy and comfort in your love, because the hearts of the saints have been refreshed through you, brother.","For we have much joy and comfort in your love, because the hearts of the saints have been refreshed through you, brother.",null],[1,8,"Therefore though I have all boldness in Christ to command you that which is appropriate,","Therefore though I have all boldness in Christ to command you that which is appropriate,",null],[1,9,"yet for love’s sake I rather appeal to you, being such a one as Paul, the aged, but also a prisoner of Jesus Christ.","yet for love’s sake I rather appeal to you, being such a one as Paul, the aged, but also a prisoner of Jesus Christ.",null],[1,10,"I appeal to you for my child Onesimus, whom I have become the father of in my chains,","I appeal to you for my child Onesimus, whom I have become the father of in my chains,",null],[1,11,"who once was useless to you, but now is useful to you and to me.","who once was useless to you, but now is useful to you and to me.",null],[1,12,"I am sending him back. Therefore receive him, that is, my own heart,","I am sending him back. Therefore receive him, that is, my own heart,",null],[1,13,"whom I desired to keep with me, that on your behalf he might serve me in my chains for the Good News.","whom I desired to keep with me, that on your behalf he might serve me in my chains for the Good News.",null],[1,14,"But I was willing to do nothing without your consent, that your goodness would not be as of necessity, but of free will.","But I was willing to do nothing without your consent, that your goodness would not be as of necessity, but of free will.",null],[1,15,"For perhaps he was therefore separated from you for a while that you would have him forever,","For perhaps he was therefore separated from you for a while that you would have him forever,",null],[1,16,"no longer as a slave, but more than a slave, a beloved brother—especially to me, but how much rather to you, both in the flesh and in the Lord.","no longer as a slave, but more than a slave, a beloved brother—especially to me, but how much rather to you, both in the flesh and in the Lord.",null],[1,17,"If then you count me a partner, receive him as you would receive me.","If then you count me a partner, receive him as you would receive me.",null],[1,18,"But if he has wronged you at all or owes you anything, put that to my account.","But if he has wronged you at all or owes you anything, put that to my account.",null],[1,19,"I, Paul, write this with my own hand: I will repay it (not to mention to you that you owe to me even your own self besides).","I, Paul, write this with my own hand: I will repay it (not to mention to you that you owe to me even your own self besides).",null],[1,20,"Yes, brother, let me have joy from you in the Lord. Refresh my heart in the Lord.","Yes, brother, let me have joy from you in the Lord. Refresh my heart in the Lord.",null],[1,21,"Having confidence in your obedience, I write to you, knowing that you will do even beyond what I say.","Having confidence in your obedience, I write to you, knowing that you will do even beyond what I say.",null],[1,22,"Also, prepare a guest room for me, for I hope that through your prayers I will be restored to you.","Also, prepare a guest room for me, for I hope that through your prayers I will be restored to you.",null],[1,23,"Epaphras, my fellow prisoner in Christ Jesus, greets you,","Epaphras, my fellow prisoner in Christ Jesus, greets you,",null],[1,24,"as do Mark, Aristarchus, Demas, and Luke, my fellow workers.","as do Mark, Aristarchus, Demas, and Luke, my fellow workers.",null],[1,25,"The grace of our Lord Jesus Christ be with your spirit. Amen.","The grace of our Lord Jesus Christ be with your spirit. Amen.",null]]}};
